import csv
import math
from collections import defaultdict


# ==========================================
# PLIKI
# ==========================================

plik_predykcja_klasyfikator = "./dane/dataBase_futbol_trend_klasyfikator.csv"

plik_historia_klasyfikator = "./dane/kod_dataBase_futbol_trend_klasyfikator.csv"

plik_historia_pelna = "./dane/kod_dataBase_futbol_trend.csv"

plik_wyj = "./dane/dopasowane_trendy_historyczne.csv"

plik_wagi = "./dane/wagi_dopasowania.csv"



# ==========================================
# PARAMETR PODOBIEŃSTWA
# ==========================================

PROG = 0.03



# ==========================================
# 6 CECH DO PORÓWNANIA
# ==========================================

LOG_INDEXY_KLASYFIKATOR = [
    1,
    2,
    3,
    4,
    5,
    6
]



# ==========================================
# FUNKCJE
# ==========================================

def liczba(x):

    try:
        return float(x)

    except:
        return 0.0



def odleglosc(a,b):

    suma = 0

    for x,y in zip(a,b):

        suma += (x-y)**2


    return math.sqrt(suma)



def wynik_liczbowy(wynik):

    try:

        g1,g2 = wynik.split(":")

        g1=int(g1)
        g2=int(g2)


        if g1>g2:
            return 1

        elif g1==g2:
            return 0

        else:
            return -1

    except:

        return 0



# ==========================================
# PEŁNA HISTORIA
# ==========================================

pelna_historia = {}


with open(
    plik_historia_pelna,
    "r",
    encoding="utf-8",
    newline=""
) as f:


    reader = csv.reader(
        f,
        delimiter=";"
    )


    for rekord in reader:


        if len(rekord) < 42:
            continue


        pelna_historia[rekord[0]] = rekord



print(
    "Pełna baza:",
    len(pelna_historia)
)



# ==========================================
# HISTORIA KLASYFIKATOR
# ==========================================

historia_klasyfikator=[]


with open(
    plik_historia_klasyfikator,
    "r",
    encoding="utf-8",
    newline=""
) as f:


    reader=csv.reader(
        f,
        delimiter=";"
    )


    next(reader)


    for rekord in reader:


        if len(rekord)<8:
            continue



        profil=[

            liczba(rekord[i])

            for i in LOG_INDEXY_KLASYFIKATOR

        ]



        historia_klasyfikator.append(

            {
                "id":rekord[0],
                "profil":profil,
                "wynik":rekord[-1]
            }

        )



print(
    "Historia klasyfikator:",
    len(historia_klasyfikator)
)



# ==========================================
# OTWARCIE PLIKÓW
# ==========================================

with open(
    plik_predykcja_klasyfikator,
    "r",
    encoding="utf-8",
    newline=""
) as f_in,\
open(
    plik_wyj,
    "w",
    encoding="utf-8",
    newline=""
) as f_out,\
open(
    plik_wagi,
    "w",
    encoding="utf-8",
    newline=""
) as f_wagi:



    reader=csv.reader(
        f_in,
        delimiter=";"
    )


    writer=csv.writer(
        f_out,
        delimiter=";"
    )


    writer_wagi=csv.writer(
        f_wagi,
        delimiter=";"
    )



    next(reader)



    # nagłówek pełnej bazy

    naglowek_hist = [

        "id_meczu",
        "zmiana_1",
        "zmiana_X",
        "zmiana_2",
        "amplituda_1",
        "amplituda_X",
        "amplituda_2",
        "tempo_1",
        "tempo_X",
        "tempo_2",
        "synchronizacja",
        "max_wahanie_1",
        "max_wahanie_X",
        "max_wahanie_2",
        "start_1_raw",
        "start_X_raw",
        "start_2_raw",
        "koniec_1_raw",
        "koniec_X_raw",
        "koniec_2_raw",
        "log_start_1",
        "log_start_X",
        "log_start_2",
        "log_koniec_1",
        "log_koniec_X",
        "log_koniec_2",
        "ratio_1X_start",
        "ratio_1_2_start",
        "ratio_X2_start",
        "ratio_1X_koniec",
        "ratio_1_2_koniec",
        "ratio_X2_koniec",
        "mean_1",
        "mean_X",
        "mean_2",
        "median_1",
        "median_X",
        "median_2",
        "stdev_1",
        "stdev_X",
        "stdev_2",
        "czas_h",
        "wynik"
    ]



    writer.writerow(

        [
            "id_meczu_predykcja",
            "odleglosc"
        ]

        +

        naglowek_hist

    )



    writer_wagi.writerow(

        [
            "id_meczu_predykcja",
            "liczba_dopasowanych",
            "sredni_wynik"
        ]

    )



    licznik_globalny=0



    # ======================================
    # MECZE PREDYKCYJNE
    # ======================================

    for mecz_pred in reader:


        profil_pred=[

            liczba(mecz_pred[i])

            for i in LOG_INDEXY_KLASYFIKATOR

        ]


        znalezone=[]



        for historia in historia_klasyfikator:


            dystans=odleglosc(

                profil_pred,
                historia["profil"]

            )


            if dystans <= PROG:

                znalezone.append(

                    (
                        dystans,
                        historia["id"],
                        historia["wynik"]

                    )

                )



        print(
            mecz_pred[0],
            "->",
            len(znalezone)
        )



        suma_wynikow=0



        for dystans,id_historyczny,wynik in znalezone:


            if id_historyczny in pelna_historia:


                rekord=pelna_historia[id_historyczny]


                writer.writerow(

                    [
                        mecz_pred[0],
                        round(dystans,8)

                    ]

                    +

                    rekord

                )


                suma_wynikow += wynik_liczbowy(wynik)


                licznik_globalny+=1




        # zapis pomocniczy

        if len(znalezone)>0:

            sredni = round(
                suma_wynikow / len(znalezone),
                4
            )

        else:

            sredni = 0



        writer_wagi.writerow(

            [
                mecz_pred[0],
                len(znalezone),
                sredni
            ]

        )



print()
print("==============================")
print("Gotowe")
print("Dane:",plik_wyj)
print("Wagi:",plik_wagi)
print("Rekordy:",licznik_globalny)
print("==============================")





