import pandas as pd
import numpy as np
import math
import csv


# =================================================
# PLIKI
# =================================================

plik_wejscie = "./dane/dopasowane_trendy_historyczne.csv"

plik_wynik = "./dane/predykcja_poisson_dc_v2.csv"


# =================================================
# PARAMETRY
# =================================================

MAX_GOLE = 8

RHO_DIXON = -0.1



# =================================================
# WCZYTANIE
# =================================================


df = pd.read_csv(

    plik_wejscie,

    sep=";"

)


print()

print("==============================")

print(" MODEL POISSON DC V2 ")

print("==============================")

print()

print(

    "Liczba meczów:",

    len(df)

)



# =================================================
# ROZBICIE WYNIKU
# =================================================


def rozbij_wynik(x):

    try:

        a,b = x.split(":")

        return int(a), int(b)

    except:

        return 0,0



df["gole_dom"] = df["wynik"].apply(

    lambda x:

    rozbij_wynik(x)[0]

)



df["gole_wyj"] = df["wynik"].apply(

    lambda x:

    rozbij_wynik(x)[1]

)



# =================================================
# WYDOBYCIE DRUŻYN
# =================================================


def pobierz_druzyny(x):

    try:

        if "-" in x:

            a,b = x.split("-")

            return (

                a.strip(),

                b.strip()

            )


        elif " vs " in x:

            a,b = x.split(" vs ")

            return (

                a.strip(),

                b.strip()

            )


    except:

        pass


    return (

        "DOM",

        "WYJAZD"

    )



kolumna_mecz = None


for k in [

    "id_mecz",

    "id_meczu",

    "id_meczu_predykcja"

]:

    if k in df.columns:

        kolumna_mecz = k

        break



if kolumna_mecz is None:

    raise Exception(

        "Brak kolumny z nazwą meczu"

    )



df["gospodarz"] = df[kolumna_mecz].apply(

    lambda x:

    pobierz_druzyny(str(x))[0]

)



df["gosc"] = df[kolumna_mecz].apply(

    lambda x:

    pobierz_druzyny(str(x))[1]

)



# =================================================
# SIŁA ATAKU
# =================================================


srednia_goli = (

    df["gole_dom"]

    .mean()

)



srednia_goli_wyj = (

    df["gole_wyj"]

    .mean()

)



atak_dom = (

    df.groupby("gospodarz")

    ["gole_dom"]

    .mean()

    /

    srednia_goli

)



atak_wyj = (

    df.groupby("gosc")

    ["gole_wyj"]

    .mean()

    /

    srednia_goli_wyj

)



# =================================================
# SIŁA OBRONY
# =================================================


obrona_dom = (

    df.groupby("gospodarz")

    ["gole_wyj"]

    .mean()

    /

    srednia_goli_wyj

)



obrona_wyj = (

    df.groupby("gosc")

    ["gole_dom"]

    .mean()

    /

    srednia_goli

)



# =================================================
# POISSON
# =================================================


def poisson(k, lam):

    if lam <= 0:

        return 0


    return (

        math.exp(-lam)

        *

        lam**k

        /

        math.factorial(k)

    )



# =================================================
# DIXON COLES
# =================================================


def dixon_coles(

        gd,

        gw,

        ld,

        lw

):


    rho = RHO_DIXON


    if gd==0 and gw==0:

        return 1 - ld*lw*rho


    if gd==1 and gw==0:

        return 1 + lw*rho


    if gd==0 and gw==1:

        return 1 + ld*rho


    if gd==1 and gw==1:

        return 1-rho


    return 1



# =================================================
# MACIERZ WYNIKÓW
# =================================================


def macierz_wynikow(ld,lw):


    wyniki=[]


    for gd in range(MAX_GOLE+1):

        for gw in range(MAX_GOLE+1):


            p=(

                poisson(gd,ld)

                *

                poisson(gw,lw)

                *

                dixon_coles(

                    gd,

                    gw,

                    ld,

                    lw

                )

            )


            wyniki.append(

                (

                    gd,

                    gw,

                    p

                )

            )


    return sorted(

        wyniki,

        key=lambda x:x[2],

        reverse=True

    )



# =================================================
# PREDYKCJA
# =================================================


wyniki=[]


for _,row in df.iterrows():


    dom=row["gospodarz"]

    gosc=row["gosc"]



    attack_dom = atak_dom.get(

        dom,

        1

    )


    attack_gosc = atak_wyj.get(

        gosc,

        1

    )


    defence_gosc = obrona_wyj.get(

        gosc,

        1

    )


    defence_dom = obrona_dom.get(

        dom,

        1

    )


    lambda_dom = (

        srednia_goli

        *

        attack_dom

        *

        defence_gosc

    )



    lambda_wyj = (

        srednia_goli_wyj

        *

        attack_gosc

        *

        defence_dom

    )



    tabela = macierz_wynikow(

        lambda_dom,

        lambda_wyj

    )


    najlepszy=tabela[0]



    gd,gw,p=najlepszy



    if gd>gw:

        typ="1"


    elif gd==gw:

        typ="X"


    else:

        typ="2"



    wyniki.append(

        {

        "mecz":row[kolumna_mecz],

        "lambda_dom":round(lambda_dom,3),

        "lambda_wyj":round(lambda_wyj,3),

        "wynik_model":f"{gd}:{gw}",

        "prawdopodobienstwo":round(p,5),

        "typ":typ

        }

    )



# =================================================
# ZAPIS
# =================================================


df_out=pd.DataFrame(

    wyniki

)



df_out.to_csv(

    plik_wynik,

    sep=";",

    index=False,

    encoding="utf-8"

)



print()

print(

    "Zapisano:",

    plik_wynik

)


print()

print("==============================")

print(" KONIEC MODEL V2 ")

print("==============================")


import csv
import os
import json
from collections import defaultdict



# ==========================================
# POPRAWA WYNIKU
# 3.0 -> 3:0
# 3:0 zostaje
# ==========================================

def popraw_wynik(wynik):

    wynik = wynik.strip()

    if "." in wynik:

        wynik = wynik.replace(
            ".",
            ":"
        )

    return wynik




# ==========================================
# WCZYTYWANIE CSV
# FORMAT:
#
# index 0 = mecz
# index 1 = grupa/tag
# index 2 = wynik
#
# ==========================================

def load_csv(
        file_path,
        delimiter=';',
        encoding='utf-8'
):

    data = []


    with open(
        file_path,
        'r',
        encoding=encoding,
        errors="ignore",
        newline=""
    ) as file:


        reader = csv.reader(
            file,
            delimiter=delimiter
        )


        for row in reader:


            if len(row) >= 3:


                row[2] = popraw_wynik(
                    row[2]
                )


                data.append(
                    row
                )


    return data




# ==========================================
# TWORZENIE MAPY TAGÓW
#
# GRUPA
#   |
#   +-- mecz
#   +-- wynik
#
# ==========================================

def create_tag_map(data):


    tag_map = defaultdict(list)



    for row in data:


        if len(row) < 3:

            continue



        mecz = row[0].strip()

        grupa = row[1].strip()

        wynik = row[2].strip()



        rekord = {

            "mecz": mecz,

            "wynik": wynik

        }



        tag_map[grupa].append(
            rekord
        )



    return tag_map




# ==========================================
# ZAPIS CSV GRUPOWANY
# (opcjonalny pomocniczy)
# ==========================================


import pandas as pd
import numpy as np


from sklearn.ensemble import RandomForestClassifier
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler



# ============================================================
# PLIKI
# ============================================================


PLIK_TRENING = r"dane\mozg_kursy_przygotowane.csv"

OUTPUT = r"dane\ranking_cech_kursy_przygotowane.csv"



# ============================================================
# NAZWY KOLUMN
# (plik treningowy NIE posiada nagłówka)
# ============================================================


KOLUMNY = [

    "mecz",

    "kurs_1_start",
    "kurs_X_start",
    "kurs_2_start",

    "kurs_1_koniec",
    "kurs_X_koniec",
    "kurs_2_koniec",

    "zmiana_kurs_1",
    "zmiana_kurs_X",
    "zmiana_kurs_2",

    "procent_kurs_1",
    "procent_kurs_X",
    "procent_kurs_2",

    "wynik"

]



# ============================================================
# WCZYTANIE PLIKU BEZ NAGŁÓWKA
# ============================================================


df = pd.read_csv(

    PLIK_TRENING,

    sep=";",

    header=None,

    names=KOLUMNY,

    encoding="utf-8"

)



print(
    "Wczytano rekordów:",
    len(df)
)



# ============================================================
# KONWERSJA WYNIKU NA KLASĘ
# ============================================================


def klasyfikuj_wynik(wynik):

    try:

        if pd.isna(wynik):
            return None


        wynik = str(wynik).strip()


        if ":" not in wynik:
            return None


        gospodarz, gosc = wynik.split(":")


        gospodarz = int(gospodarz)

        gosc = int(gosc)



        if gospodarz > gosc:

            return 1


        elif gospodarz == gosc:

            return 0


        else:

            return -1



    except:

        return None



df["klasa"] = df["wynik"].apply(
    klasyfikuj_wynik
)



# usunięcie braków

df = df.dropna(
    subset=["klasa"]
)



print(
    "Mecze po klasyfikacji:",
    len(df)
)



# ============================================================
# PRZYGOTOWANIE CECH
# ============================================================


CECHY = [

    c for c in KOLUMNY

    if c not in [

        "mecz",

        "wynik"

    ]

]



X = df[CECHY]


y = df["klasa"]



# wszystkie kursy jako liczby

X = X.apply(

    pd.to_numeric,

    errors="coerce"

)



X = X.fillna(0)



# ============================================================
# KORELACJA DC
# ============================================================


korelacja = {}


for cecha in CECHY:


    korelacja[cecha] = abs(

        np.corrcoef(

            X[cecha],

            y

        )[0,1]

    )



korelacja = pd.Series(
    korelacja
)



korelacja = korelacja.fillna(0)



# ============================================================
# RANDOM FOREST
# ============================================================


rf = RandomForestClassifier(

    n_estimators=500,

    random_state=42,

    class_weight="balanced"

)


rf.fit(

    X,

    y

)



rf_score = pd.Series(

    rf.feature_importances_,

    index=CECHY

)



# ============================================================
# DC - MUTUAL INFORMATION
# ============================================================


scaler = StandardScaler()


X_scaled = scaler.fit_transform(

    X

)



dc = mutual_info_classif(

    X_scaled,

    y,

    random_state=42

)



dc_score = pd.Series(

    dc,

    index=CECHY

)



# ============================================================
# NORMALIZACJA
# ============================================================


def normalizuj(x):

    if x.max() == x.min():

        return x * 0


    return (

        x - x.min()

    ) / (

        x.max() - x.min()

    )



korelacja_n = normalizuj(
    korelacja
)


rf_n = normalizuj(
    rf_score
)


dc_n = normalizuj(
    dc_score
)



# ============================================================
# BUDOWA RANKINGU
# ============================================================


ranking = pd.DataFrame()


ranking["cecha"] = CECHY


ranking["korelacja_dc"] = (

    korelacja_n.values

)


ranking["RF"] = (

    rf_n.values

)


ranking["DC"] = (

    dc_n.values

)



# końcowa siła

ranking["sila"] = (

    ranking["korelacja_dc"] * 0.4

    +

    ranking["RF"] * 0.3

    +

    ranking["DC"] * 0.3

)



ranking = ranking.sort_values(

    by="sila",

    ascending=False

)



# ============================================================
# ZAPIS
# ============================================================


ranking.to_csv(

    OUTPUT,

    sep=";",

    index=False,

    encoding="utf-8"

)



print()

print(
    "Gotowe:",
    OUTPUT
)


print(
    ranking.head(20)
)



import os
