import os
import json
import pandas as pd
import numpy as np

from sklearn.ensemble import RandomForestClassifier
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler



# ============================================================
# KONFIGURACJA
# ============================================================

BASE_DIR = os.path.dirname(
    os.path.abspath(__file__)
)


DATA_DIR = os.path.join(
    BASE_DIR,
    "dane"
)



PLIKI = [

    "dopasowane_trendy_historyczne.csv",


]



# ============================================================
# KLASYFIKACJA WYNIKU
# ============================================================


def klasyfikuj_wynik(wynik):

    try:

        wynik = str(wynik).strip()


        if ":" not in wynik:

            return None


        dom, wyjazd = wynik.split(":")


        dom = int(dom)

        wyjazd = int(wyjazd)



        if dom > wyjazd:

            return 1


        elif dom == wyjazd:

            return 0


        else:

            return -1


    except:

        return None



# ============================================================
# NORMALIZACJA
# ============================================================


def normalizuj(x):


    if x.max() == x.min():

        return x * 0


    return (

        x - x.min()

    ) / (

        x.max() - x.min()

    )



# ============================================================
# KORELACJA BEZ OSTRZEŻEŃ
# ============================================================


def policz_korelacje(cecha, y):


    try:

        if cecha.std() == 0:

            return 0


        wynik = np.corrcoef(

            cecha,

            y

        )[0,1]


        if np.isnan(wynik):

            return 0


        return abs(wynik)


    except:

        return 0



# ============================================================
# ANALIZA JEDNEGO PLIKU
# ============================================================


def analizuj_plik(nazwa_pliku):


    INPUT = os.path.join(

        DATA_DIR,

        nazwa_pliku

    )



    nazwa_json = nazwa_pliku.replace(

        ".csv",

        ".json"

    )



    OUTPUT = os.path.join(

        DATA_DIR,

        nazwa_json

    )



    print()
    print("="*70)
    print("ANALIZA ŚWIATA:")
    print(nazwa_pliku)
    print("="*70)



    df = pd.read_csv(

        INPUT,

        sep=";",

        encoding="utf-8"

    )



    print(
        "Rekordów:",
        len(df)
    )



    kolumny = list(
        df.columns
    )



    # --------------------------------------------------------
    # STAŁE STRUKTURY
    # --------------------------------------------------------


    ID_PRED = kolumny[0]

    ILOSC_DOPASOWAN = kolumny[1]

    ID_HISTORYCZNE = kolumny[2]

    WYNIK = kolumny[-1]



    # dynamiczne cechy

    CECHY = [

        ILOSC_DOPASOWAN

    ] + kolumny[3:-1]



    print(
        "Cechy:",
        CECHY
    )



    WORLD_MEMORY = {

        "plik_zrodlo": nazwa_pliku,

        "liczba_rekordow": len(df),

        "swiaty": {}

    }



    # ========================================================
    # KAŻDY MECZ PREDYKCYJNY OSOBNO
    # ========================================================


    for id_predykcji, grupa in df.groupby(
        ID_PRED
    ):


        print()

        print(
            "ŚWIAT:",
            id_predykcji
        )


        print(
            "Historia:",
            len(grupa)
        )



        dane = grupa.copy()



        dane["klasa"] = dane[WYNIK].apply(

            klasyfikuj_wynik

        )



        dane = dane.dropna(

            subset=[

                "klasa"

            ]

        )



        if len(dane) < 5:

            print(
                "Za mało danych"
            )

            continue



        X = dane[CECHY].copy()


        y = dane["klasa"]



        X = X.apply(

            pd.to_numeric,

            errors="coerce"

        )


        X = X.fillna(0)



        # ----------------------------------------------------
        # KORELACJA
        # ----------------------------------------------------


        korelacja = {}


        for cecha in CECHY:


            korelacja[cecha] = policz_korelacje(

                X[cecha],

                y

            )



        korelacja = pd.Series(

            korelacja

        )



        # ----------------------------------------------------
        # RANDOM FOREST
        # ----------------------------------------------------


        rf = RandomForestClassifier(

            n_estimators=300,

            random_state=42,

            class_weight="balanced"

        )



        rf.fit(

            X,

            y

        )



        rf_score = pd.Series(

            rf.feature_importances_,

            index=CECHY

        )



        # ----------------------------------------------------
        # MUTUAL INFORMATION
        # ----------------------------------------------------


        scaler = StandardScaler()



        X_scaled = scaler.fit_transform(

            X

        )



        dc = mutual_info_classif(

            X_scaled,

            y,

            random_state=42

        )



        dc_score = pd.Series(

            dc,

            index=CECHY

        )



        # ----------------------------------------------------
        # NORMALIZACJA
        # ----------------------------------------------------


        korelacja_n = normalizuj(

            korelacja

        )


        rf_n = normalizuj(

            rf_score

        )


        dc_n = normalizuj(

            dc_score

        )



        ranking = []



        for cecha in CECHY:


            ranking.append(

                {

                "cecha": cecha,

                "korelacja": float(

                    korelacja_n[cecha]

                ),

                "RF": float(

                    rf_n[cecha]

                ),

                "DC": float(

                    dc_n[cecha]

                ),

                "sila": float(

                    korelacja_n[cecha] * 0.4

                    +

                    rf_n[cecha] * 0.3

                    +

                    dc_n[cecha] * 0.3

                )

                }

            )



        ranking = sorted(

            ranking,

            key=lambda x:

            x["sila"],

            reverse=True

        )



        WORLD_MEMORY["swiaty"][id_predykcji] = {


            "ilosc_dopasowan": int(

                grupa[ILOSC_DOPASOWAN].iloc[0]

            ),


            "liczba_historycznych_meczow": len(grupa),


            "ranking_cech": ranking


        }



    # ========================================================
    # ZAPIS JSON
    # ========================================================


    with open(

        OUTPUT,

        "w",

        encoding="utf-8"

    ) as plik:


        json.dump(

            WORLD_MEMORY,

            plik,

            indent=4,

            ensure_ascii=False

        )



    print()

    print(
        "ZAPISANO:"
    )

    print(
        OUTPUT
    )



# ============================================================
# START
# ============================================================


for plik in PLIKI:


    analizuj_plik(

        plik

    )



print()
print("="*70)
print("WSZYSTKIE ŚWIATY ZBUDOWANE")
print("="*70)


