def zbuduj_poziomy(grupa):


    elementy = grupa.split(
        "poziom"
    )


    poziomy = []



    for e in elementy:


        if e.strip():

            poziomy.append(

                "poziom" + e.strip()

            )



    wynik = {


        "level_1":
            None,


        "level_2":
            None,


        "full":
            grupa

    }



    if len(poziomy) >= 1:

        wynik["level_1"] = poziomy[0]



    if len(poziomy) >= 2:

        wynik["level_2"] = (

            poziomy[0]

            +

            poziomy[1]

        )



    return wynik







