# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 1/2
# =====================================================


import os
import json
import pandas as pd
import numpy as np

from datetime import datetime

from tensorflow.keras.models import load_model



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = r"modele_dataBase_futbol_trend\siec_04_max_wahanie"


PLIK_PREDYKCJI = r"dane\dataBase_futbol_trend.csv"


PLIK_HISTORIA = r"dane\kod_dataBase_futbol_trend.csv"



KATALOG_OBSERWACJI = os.path.join(
    KATALOG_MODELU,
    "obserwacja"
)


KATALOG_PREDYKCJI = os.path.join(
    KATALOG_MODELU,
    "predykcje"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_OBSERWACJI,
    "pamiec_obserwacji.json"
)



PLIK_OCENA = os.path.join(
    KATALOG_OBSERWACJI,
    "ocena.json"
)



os.makedirs(
    KATALOG_OBSERWACJI,
    exist_ok=True
)



os.makedirs(
    KATALOG_PREDYKCJI,
    exist_ok=True
)





# =====================================================
# WCZYTANIE METADANYCH MODELU
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "metadata.json"
    ),

    encoding="utf-8"

) as f:

    metadata = json.load(f)



CECHY = metadata["cechy"]


NAZWA_MODELU = metadata["nazwa"]





# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "klasy.json"
    ),

    encoding="utf-8"

) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v): k

    for k,v in klasy.items()

}





# =====================================================
# WCZYTANIE AKTUALNEJ PREDYKCJI
# =====================================================


df_pred = pd.read_csv(

    PLIK_PREDYKCJI,

    sep=";",

    encoding="utf-8"

)



INDEX_MAP = {


    kolumna:index

    for index,kolumna

    in enumerate(df_pred.columns)

}



print("MAPA CECH")

print(INDEX_MAP)





# =====================================================
# CECHY MODELU
# =====================================================


INDEX_CECH = []



for cecha in CECHY:


    if cecha not in INDEX_MAP:


        raise Exception(

            f"Brak cechy modelu: {cecha}"

        )


    INDEX_CECH.append(

        INDEX_MAP[cecha]

    )



print(

    "Cechy modelu:",

    INDEX_CECH

)





# =====================================================
# AKTUALNE MECZE DO PREDYKCJI
# =====================================================


NAZWY_PREDYKCJI = (

    df_pred["id_meczu"]

    .astype(str)

    .tolist()

)



X_PREDYKCJA = df_pred.iloc[

    :,

    INDEX_CECH

]



X_PREDYKCJA = np.nan_to_num(

    X_PREDYKCJA.values

)





# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


hist = pd.read_csv(

    PLIK_HISTORIA,

    sep=";",

    header=None,

    encoding="utf-8"

)



NAZWY_HISTORIA = hist.iloc[:,0].astype(str)



X_HISTORIA = hist.iloc[

    :,

    INDEX_CECH

]



Y_HISTORIA = hist.iloc[:,-1]



X_HISTORIA = np.nan_to_num(

    X_HISTORIA.values

)





# =====================================================
# WCZYTANIE MODELU
# =====================================================


model = load_model(

    os.path.join(

        KATALOG_MODELU,

        "model.h5"

    )

)





# =====================================================
# PREDYKCJA HISTORII
# =====================================================


print(
    "Analiza historii..."
)



pred_hist = model.predict(

    X_HISTORIA

)



klasy_pred_hist = np.argmax(

    pred_hist,

    axis=1

)





# =====================================================
# PREDYKCJA AKTUALNYCH MECZÓW
# =====================================================


print(

    "Analiza aktualnych meczów..."

)



pred = model.predict(

    X_PREDYKCJA

)



klasy_pred = np.argmax(

    pred,

    axis=1

)





# =====================================================
# WCZYTANIE PAMIĘCI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:


        pamiec_obserwacji = json.load(f)



else:


    pamiec_obserwacji = {}





# =====================================================
# WCZYTANIE OCENY
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:


        ocena = json.load(f)



else:


    ocena = {


        "model":

        NAZWA_MODELU,


        "ocena_ogolna":

        {

            "ilosc":

            0,


            "trafienia":

            0

        },


        "ocena_wynikow":

        {}

    }





# =====================================================
# STRUKTURY SESJI
# =====================================================


czas = datetime.now().strftime(

    "%Y-%m-%d %H:%M:%S"

)



nowe_obserwacje = []


nowe_predykcje = []


nowa_historia = []




analiza = {}



for wynik in klasy.keys():


    analiza[wynik] = {


        "ilosc_wystapien":0,


        "trafienia":0,


        "bledy":{}

    }




print(

    "Przygotowano dane."

)
# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 2/2
# =====================================================



# =====================================================
# ANALIZA HISTORII Z WYNIKAMI
# =====================================================


for i,p in enumerate(klasy_pred_hist):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    real_wynik = str(
        Y_HISTORIA.iloc[i]
    )


    nazwa_meczu = str(
        NAZWY_HISTORIA.iloc[i]
    )


    pewnosc = float(
        np.max(pred_hist[i])
    )


    trafienie = (
        pred_wynik == real_wynik
    )



    obserwacja = {


        "data":

        czas,


        "model":

        NAZWA_MODELU,


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "predykcja":

        pred_wynik,


        "wynik_rzeczywisty":

        real_wynik,


        "pewnosc":

        pewnosc,


        "trafienie":

        trafienie

    }





    # =========================================
    # AKTUALIZACJA PAMIĘCI MECZU
    # =========================================


    if nazwa_meczu not in pamiec_obserwacji:


        pamiec_obserwacji[nazwa_meczu] = []



        obserwacja["pierwsza_obserwacja"] = True



    else:


        ostatnia = pamiec_obserwacji[nazwa_meczu][-1]



        if ostatnia["predykcja"] != pred_wynik:


            obserwacja["zmiana_predykcji"] = {


                "stara":

                ostatnia["predykcja"],


                "nowa":

                pred_wynik

            }



        if ostatnia["pewnosc"] != pewnosc:


            obserwacja["zmiana_pewnosci"] = {


                "stara":

                ostatnia["pewnosc"],


                "nowa":

                pewnosc

            }





    pamiec_obserwacji[nazwa_meczu].append(

        obserwacja

    )



    nowe_obserwacje.append(

        obserwacja

    )





    # statystyka klasy


    analiza[pred_wynik]["ilosc_wystapien"] += 1



    if trafienie:


        analiza[pred_wynik]["trafienia"] += 1


    else:


        if real_wynik not in analiza[pred_wynik]["bledy"]:


            analiza[pred_wynik]["bledy"][real_wynik] = 0



        analiza[pred_wynik]["bledy"][real_wynik] += 1







# =====================================================
# AKTUALNE MECZE BEZ WYNIKU
# =====================================================


for i,p in enumerate(klasy_pred):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    nazwa_meczu = str(

        NAZWY_PREDYKCJI[i]

    )


    pewnosc = float(

        np.max(pred[i])

    )



    predykcja = {


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "wynik_predykcji":

        pred_wynik,


        "pewnosc":

        pewnosc

    }



    nowe_predykcje.append(

        predykcja

    )







# =====================================================
# AKTUALIZACJA OCENY MODELU
# =====================================================


ilosc_globalna = 0

trafienia_globalne = 0



ocena_wynikow = {}



for wynik,dane in analiza.items():


    ilosc = dane["ilosc_wystapien"]


    trafienia = dane["trafienia"]



    ilosc_globalna += ilosc


    trafienia_globalne += trafienia



    ocena_wynikow[wynik] = {


        "ilosc_predykcji":

        ilosc,


        "trafienia":

        trafienia,


        "skutecznosc":

        (

            trafienia / ilosc

            if ilosc > 0

            else 0

        ),


        "bledy":

        dane["bledy"]

    }





ocena = {


    "model":

    NAZWA_MODELU,


    "data":

    czas,


    "ocena_ogolna":{


        "ilosc_meczow":

        ilosc_globalna,


        "trafienia":

        trafienia_globalne,


        "skutecznosc":

        (

            trafienia_globalne /

            ilosc_globalna

            if ilosc_globalna > 0

            else 0

        )

    },


    "ocena_wynikow":

    ocena_wynikow

}







# =====================================================
# ZAPIS PAMIĘCI
# =====================================================


with open(

    PLIK_PAMIEC,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        pamiec_obserwacji,

        f,

        indent=4,

        ensure_ascii=False

    )





# =====================================================
# ZAPIS OCENY
# =====================================================


with open(

    PLIK_OCENA,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        ocena,

        f,

        indent=4,

        ensure_ascii=False

    )







# =====================================================
# ZAPIS AKTUALNEJ PREDYKCJI
# =====================================================


pd.DataFrame(

    nowe_predykcje

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







# =====================================================
# ZAPIS HISTORII Z WYNIKAMI
# =====================================================


historia_csv = []



for mecz,lista in pamiec_obserwacji.items():


    ostatnia = lista[-1]


    historia_csv.append(


        {


            "id_meczu":

            mecz,


            "id_grupy":

            ostatnia["id_grupy"],


            "wynik_predykcji":

            ostatnia["predykcja"],


            "pewnosc":

            ostatnia["pewnosc"],


            "wynik_rzeczywisty":

            ostatnia["wynik_rzeczywisty"]

        }

    )







pd.DataFrame(

    historia_csv

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







print()

print("================================")

print("ZAKOŃCZONO")

print("================================")



print(

    "Pamięć:",

    PLIK_PAMIEC

)



print(

    "Ocena:",

    PLIK_OCENA

)



print(

    "Predykcje:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    )

)



print(

    "Historia:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    )

)
