import os
import json
import pandas as pd
import numpy as np

from datetime import datetime



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = (
    r"modele_dataBase_futbol_trend"
    r"\siec_08_log_koniec"
)


NAZWA_BAZY = "dataBase_futbol_trend"


NAZWA_MODELU = os.path.basename(
    KATALOG_MODELU
)



# =====================================================
# LABORATORIUM
# =====================================================


KATALOG_LABORATORIUM = os.path.join(
    "laboratorium",
    NAZWA_BAZY,
    NAZWA_MODELU
)



os.makedirs(
    KATALOG_LABORATORIUM,
    exist_ok=True
)



# =====================================================
# PLIKI WEJŚCIOWE
# =====================================================


PLIK_KLASY = os.path.join(
    KATALOG_MODELU,
    "klasy.json"
)



PLIK_PRED_WYNIK = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_z_wynikiem.csv"
)



PLIK_PRED_GRUPY = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_grupy.csv"
)



PLIK_OCENA = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "ocena.json"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "pamiec_obserwacji.json"
)




# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(
    PLIK_KLASY,
    encoding="utf-8"
) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v):k

    for k,v in klasy.items()

}



print(
    "Załadowano klas:",
    len(ID_NA_WYNIK)
)



# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


df_historia = pd.read_csv(

    PLIK_PRED_WYNIK,

    sep=";",

    encoding="utf-8"

)



print(
    "Historia:",
    len(df_historia)
)



# =====================================================
# WCZYTANIE AKTUALNYCH PREDYKCJI
# =====================================================


df_predykcja = pd.read_csv(

    PLIK_PRED_GRUPY,

    sep=";",

    encoding="utf-8"

)



print(
    "Aktualne predykcje:",
    len(df_predykcja)
)



# =====================================================
# WCZYTANIE OCENY MODELU
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:

        ocena_modelu = json.load(f)


else:


    ocena_modelu = {}




# =====================================================
# WCZYTANIE PAMIĘCI OBSERWACJI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:

        pamiec_obserwacji = json.load(f)


else:


    pamiec_obserwacji = {}




print(
    "Pamięć obserwacji:",
    len(pamiec_obserwacji)
)




# =====================================================
# ANALIZA KLAS
# =====================================================


analiza_klas = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    ilosc = len(dane)



    if ilosc == 0:


        analiza_klas[str(id_grupy)] = {


            "wynik":

            wynik,


            "ilosc_predykcji":

            0,


            "trafienia":

            0,


            "skutecznosc":

            0,


            "rzeczywisty_rozkład":

            {}

        }


        continue




    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()




    rozklad = (

        dane["wynik_rzeczywisty"]

        .value_counts(normalize=True)

        .to_dict()

    )




    analiza_klas[str(id_grupy)] = {


        "wynik":

        wynik,


        "ilosc_predykcji":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        ),



        "rzeczywisty_rozkład":

        rozklad

    }




# =====================================================
# ANALIZA PEWNOŚCI DYNAMICZNA
# =====================================================


analiza_pewnosci = {}




df_historia = df_historia.sort_values(
    "pewnosc"
)




# 10 równych grup według ilości danych

df_historia["koszyk_pewnosci"] = pd.qcut(

    df_historia["pewnosc"],

    q=10,

    duplicates="drop"

)




for koszyk, dane in df_historia.groupby(

    "koszyk_pewnosci",

    observed=True

):


    ilosc = len(dane)



    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()



    analiza_pewnosci[str(koszyk)] = {


        "ilosc":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        )

    }




# =====================================================
# ANALIZA PEWNOŚCI DLA KAŻDEJ KLASY
# =====================================================


analiza_pewnosci_klasy = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane_klasy = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    if len(dane_klasy) == 0:

        continue




    dane_klasy = dane_klasy.copy()



    dane_klasy["koszyk"] = pd.qcut(

        dane_klasy["pewnosc"],

        q=10,

        duplicates="drop"

    )



    koszyki = {}



    for koszyk,dane in dane_klasy.groupby(

        "koszyk",

        observed=True

    ):



        ilosc = len(dane)



        trafienia = (

            dane["wynik_predykcji"]

            ==

            dane["wynik_rzeczywisty"]

        ).sum()



        koszyki[str(koszyk)] = {


            "ilosc":

            int(ilosc),


            "trafienia":

            int(trafienia),


            "skutecznosc":

            float(

                trafienia / ilosc

            )

        }




    analiza_pewnosci_klasy[str(id_grupy)] = {


        "wynik":

        wynik,


        "progi_pewnosci":

        koszyki

    }




# KONIEC FRAGMENTU 1/2
# =====================================================
# LABORATORIUM V2
# ANALIZA PAMIĘCI + PEWNOŚCI + KLAS + PREDYKCJI
# FRAGMENT 2/2
# =====================================================


# =====================================================
# ANALIZA ODCHYLEŃ
# (CO SIEĆ TYPOWAŁA VS CO FAKTYCZNIE WYPADŁO)
# =====================================================


analiza_odchylen = {}



for id_grupy, wynik in ID_NA_WYNIK.items():


    dane = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]


    if len(dane) == 0:

        continue



    rozklad = (

        dane["wynik_rzeczywisty"]

        .value_counts(normalize=True)

        .to_dict()

    )



    uporzadkowane = sorted(

        rozklad.items(),

        key=lambda x:x[1],

        reverse=True

    )



    analiza_odchylen[str(id_grupy)] = {


        "wynik_typowany":

        wynik,


        "ilosc":

        int(len(dane)),


        "najczestsze_wyniki_rzeczywiste":

        dict(uporzadkowane[:10]),


        "czy_odwrócony_wzorzec":

        (
            uporzadkowane[0][0] != wynik
            if len(uporzadkowane)>0
            else False
        )

    }




# =====================================================
# ANALIZA PAMIĘCI OBSERWACJI
# =====================================================


analiza_pamieci = {


    "ilosc_meczow":

    len(pamiec_obserwacji),


    "zmiany_predykcji":0,


    "pierwsze_obserwacje":0

}



for mecz, obserwacje in pamiec_obserwacji.items():


    for obs in obserwacje:


        if obs.get(
            "pierwsza_obserwacja"
        ):

            analiza_pamieci[
                "pierwsze_obserwacje"
            ] += 1



        if obs.get(
            "zmiana_predykcji"
        ):

            analiza_pamieci[
                "zmiany_predykcji"
            ] += 1




# =====================================================
# ANALIZA AKTUALNYCH PREDYKCJI
# =====================================================


analiza_przyszlych = []



for _,mecz in df_predykcja.iterrows():


    id_grupy = int(
        mecz["id_grupy"]
    )


    wynik = str(
        mecz["wynik_predykcji"]
    )


    pewnosc = float(
        mecz["pewnosc"]
    )



    wiedza = analiza_klas.get(

        str(id_grupy),

        {}

    )



    pewnosc_klasy = analiza_pewnosci_klasy.get(

        str(id_grupy),

        {}

    )



    odchylenie = analiza_odchylen.get(

        str(id_grupy),

        {}

    )


    analiza_przyszlych.append(


        {


            "id_meczu":

            mecz["id_meczu"],



            "id_grupy":

            id_grupy,



            "wynik_predykcji":

            wynik,



            "pewnosc":

            pewnosc,



            "historyczna_skutecznosc_klasy":

            wiedza.get(

                "skutecznosc",

                0

            ),



            "najczestszy_realny_wynik":

            (
                max(

                    wiedza.get(

                        "rzeczywisty_rozkład",

                        {}

                    ),

                    key=wiedza.get(

                        "rzeczywisty_rozkład",

                        {}

                    ).get

                )

                if wiedza.get(

                    "rzeczywisty_rozkład"

                )

                else None
            ),



            "czy_odwrócony_wzorzec":

            odchylenie.get(

                "czy_odwrócony_wzorzec",

                False

            )

        }

    )




df_analiza_predykcji = pd.DataFrame(

    analiza_przyszlych

)



df_analiza_predykcji.to_csv(


    os.path.join(

        KATALOG_LABORATORIUM,

        "analiza_przyszlych_predykcji.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)




# =====================================================
# KOLEKTOR WIEDZY
# =====================================================


kolektor_wiedzy = {


    "model":

    NAZWA_MODELU,



    "data":

    datetime.now().strftime(

        "%Y-%m-%d %H:%M:%S"

    ),



    "ocena_modelu":

    ocena_modelu,



    "analiza_klas":

    analiza_klas,



    "analiza_pewnosci":

    analiza_pewnosci,



    "analiza_pewnosci_klasy":

    analiza_pewnosci_klasy,



    "analiza_odchylen":

    analiza_odchylen,



    "analiza_pamieci":

    analiza_pamieci

}




# =====================================================
# ZAPIS JSON
# =====================================================


pliki_json = {


    "analiza_klas.json":

    analiza_klas,


    "analiza_pewnosci.json":

    analiza_pewnosci,


    "analiza_pewnosci_klasy.json":

    analiza_pewnosci_klasy,


    "analiza_odchylen.json":

    analiza_odchylen,


    "analiza_pamieci.json":

    analiza_pamieci,


    "kolektor_wiedzy.json":

    kolektor_wiedzy

}




for nazwa,dane in pliki_json.items():


    with open(

        os.path.join(

            KATALOG_LABORATORIUM,

            nazwa

        ),

        "w",

        encoding="utf-8"

    ) as f:


        json.dump(

            dane,

            f,

            indent=4,

            ensure_ascii=False

        )




