# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 1/2
# =====================================================


import os
import json
import pandas as pd
import numpy as np

from datetime import datetime

from tensorflow.keras.models import load_model



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = r"modele_kursy_przygotowane\siec_01_start_kursow"


PLIK_PREDYKCJI = r"dane\kursy_przygotowane.csv"


PLIK_HISTORIA = r"dane\mozg_kursy_przygotowane.csv"



KATALOG_OBSERWACJI = os.path.join(
    KATALOG_MODELU,
    "obserwacja"
)


KATALOG_PREDYKCJI = os.path.join(
    KATALOG_MODELU,
    "predykcje"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_OBSERWACJI,
    "pamiec_obserwacji.json"
)



PLIK_OCENA = os.path.join(
    KATALOG_OBSERWACJI,
    "ocena.json"
)



os.makedirs(
    KATALOG_OBSERWACJI,
    exist_ok=True
)



os.makedirs(
    KATALOG_PREDYKCJI,
    exist_ok=True
)





# =====================================================
# WCZYTANIE METADANYCH MODELU
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "metadata.json"
    ),

    encoding="utf-8"

) as f:

    metadata = json.load(f)



CECHY = metadata["cechy"]


NAZWA_MODELU = metadata["nazwa"]





# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "klasy.json"
    ),

    encoding="utf-8"

) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v): k

    for k,v in klasy.items()

}





# =====================================================
# WCZYTANIE AKTUALNEJ PREDYKCJI
# =====================================================


df_pred = pd.read_csv(

    PLIK_PREDYKCJI,

    sep=";",

    encoding="utf-8"

)



INDEX_MAP = {


    kolumna:index

    for index,kolumna

    in enumerate(df_pred.columns)

}



print("MAPA CECH")

print(INDEX_MAP)





# =====================================================
# CECHY MODELU
# =====================================================


INDEX_CECH = []



for cecha in CECHY:


    if cecha not in INDEX_MAP:


        raise Exception(

            f"Brak cechy modelu: {cecha}"

        )


    INDEX_CECH.append(

        INDEX_MAP[cecha]

    )



print(

    "Cechy modelu:",

    INDEX_CECH

)





# =====================================================
# AKTUALNE MECZE DO PREDYKCJI
# =====================================================


NAZWY_PREDYKCJI = (

    df_pred["mecz"]

    .astype(str)

    .tolist()

)



X_PREDYKCJA = df_pred.iloc[

    :,

    INDEX_CECH

]



X_PREDYKCJA = np.nan_to_num(

    X_PREDYKCJA.values

)





# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


hist = pd.read_csv(

    PLIK_HISTORIA,

    sep=";",

    header=None,

    encoding="utf-8"

)



NAZWY_HISTORIA = hist.iloc[:,0].astype(str)



X_HISTORIA = hist.iloc[

    :,

    INDEX_CECH

]



Y_HISTORIA = hist.iloc[:,-1]



X_HISTORIA = np.nan_to_num(

    X_HISTORIA.values

)





# =====================================================
# WCZYTANIE MODELU
# =====================================================


model = load_model(

    os.path.join(

        KATALOG_MODELU,

        "model.h5"

    )

)





# =====================================================
# PREDYKCJA HISTORII
# =====================================================


print(
    "Analiza historii..."
)



pred_hist = model.predict(

    X_HISTORIA

)



klasy_pred_hist = np.argmax(

    pred_hist,

    axis=1

)





# =====================================================
# PREDYKCJA AKTUALNYCH MECZÓW
# =====================================================


print(

    "Analiza aktualnych meczów..."

)



pred = model.predict(

    X_PREDYKCJA

)



klasy_pred = np.argmax(

    pred,

    axis=1

)





# =====================================================
# WCZYTANIE PAMIĘCI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:


        pamiec_obserwacji = json.load(f)



else:


    pamiec_obserwacji = {}





# =====================================================
# WCZYTANIE OCENY
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:


        ocena = json.load(f)



else:


    ocena = {


        "model":

        NAZWA_MODELU,


        "ocena_ogolna":

        {

            "ilosc":

            0,


            "trafienia":

            0

        },


        "ocena_wynikow":

        {}

    }





# =====================================================
# STRUKTURY SESJI
# =====================================================


czas = datetime.now().strftime(

    "%Y-%m-%d %H:%M:%S"

)



nowe_obserwacje = []


nowe_predykcje = []


nowa_historia = []




analiza = {}



for wynik in klasy.keys():


    analiza[wynik] = {


        "ilosc_wystapien":0,


        "trafienia":0,


        "bledy":{}

    }




print(

    "Przygotowano dane."

)
# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 2/2
# =====================================================



# =====================================================
# ANALIZA HISTORII Z WYNIKAMI
# =====================================================


for i,p in enumerate(klasy_pred_hist):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    real_wynik = str(
        Y_HISTORIA.iloc[i]
    )


    nazwa_meczu = str(
        NAZWY_HISTORIA.iloc[i]
    )


    pewnosc = float(
        np.max(pred_hist[i])
    )


    trafienie = (
        pred_wynik == real_wynik
    )



    obserwacja = {


        "data":

        czas,


        "model":

        NAZWA_MODELU,


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "predykcja":

        pred_wynik,


        "wynik_rzeczywisty":

        real_wynik,


        "pewnosc":

        pewnosc,


        "trafienie":

        trafienie

    }





    # =========================================
    # AKTUALIZACJA PAMIĘCI MECZU
    # =========================================


    if nazwa_meczu not in pamiec_obserwacji:


        pamiec_obserwacji[nazwa_meczu] = []



        obserwacja["pierwsza_obserwacja"] = True



    else:


        ostatnia = pamiec_obserwacji[nazwa_meczu][-1]



        if ostatnia["predykcja"] != pred_wynik:


            obserwacja["zmiana_predykcji"] = {


                "stara":

                ostatnia["predykcja"],


                "nowa":

                pred_wynik

            }



        if ostatnia["pewnosc"] != pewnosc:


            obserwacja["zmiana_pewnosci"] = {


                "stara":

                ostatnia["pewnosc"],


                "nowa":

                pewnosc

            }





    pamiec_obserwacji[nazwa_meczu].append(

        obserwacja

    )



    nowe_obserwacje.append(

        obserwacja

    )





    # statystyka klasy


    analiza[pred_wynik]["ilosc_wystapien"] += 1



    if trafienie:


        analiza[pred_wynik]["trafienia"] += 1


    else:


        if real_wynik not in analiza[pred_wynik]["bledy"]:


            analiza[pred_wynik]["bledy"][real_wynik] = 0



        analiza[pred_wynik]["bledy"][real_wynik] += 1







# =====================================================
# AKTUALNE MECZE BEZ WYNIKU
# =====================================================


for i,p in enumerate(klasy_pred):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    nazwa_meczu = str(

        NAZWY_PREDYKCJI[i]

    )


    pewnosc = float(

        np.max(pred[i])

    )



    predykcja = {


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "wynik_predykcji":

        pred_wynik,


        "pewnosc":

        pewnosc

    }



    nowe_predykcje.append(

        predykcja

    )







# =====================================================
# AKTUALIZACJA OCENY MODELU
# =====================================================


ilosc_globalna = 0

trafienia_globalne = 0



ocena_wynikow = {}



for wynik,dane in analiza.items():


    ilosc = dane["ilosc_wystapien"]


    trafienia = dane["trafienia"]



    ilosc_globalna += ilosc


    trafienia_globalne += trafienia



    ocena_wynikow[wynik] = {


        "ilosc_predykcji":

        ilosc,


        "trafienia":

        trafienia,


        "skutecznosc":

        (

            trafienia / ilosc

            if ilosc > 0

            else 0

        ),


        "bledy":

        dane["bledy"]

    }





ocena = {


    "model":

    NAZWA_MODELU,


    "data":

    czas,


    "ocena_ogolna":{


        "ilosc_meczow":

        ilosc_globalna,


        "trafienia":

        trafienia_globalne,


        "skutecznosc":

        (

            trafienia_globalne /

            ilosc_globalna

            if ilosc_globalna > 0

            else 0

        )

    },


    "ocena_wynikow":

    ocena_wynikow

}







# =====================================================
# ZAPIS PAMIĘCI
# =====================================================


with open(

    PLIK_PAMIEC,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        pamiec_obserwacji,

        f,

        indent=4,

        ensure_ascii=False

    )





# =====================================================
# ZAPIS OCENY
# =====================================================


with open(

    PLIK_OCENA,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        ocena,

        f,

        indent=4,

        ensure_ascii=False

    )







# =====================================================
# ZAPIS AKTUALNEJ PREDYKCJI
# =====================================================


pd.DataFrame(

    nowe_predykcje

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







# =====================================================
# ZAPIS HISTORII Z WYNIKAMI
# =====================================================


historia_csv = []



for mecz,lista in pamiec_obserwacji.items():


    ostatnia = lista[-1]


    historia_csv.append(


        {


            "id_meczu":

            mecz,


            "id_grupy":

            ostatnia["id_grupy"],


            "wynik_predykcji":

            ostatnia["predykcja"],


            "pewnosc":

            ostatnia["pewnosc"],


            "wynik_rzeczywisty":

            ostatnia["wynik_rzeczywisty"]

        }

    )







pd.DataFrame(

    historia_csv

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







print()

print("================================")

print("ZAKOŃCZONO")

print("================================")



print(

    "Pamięć:",

    PLIK_PAMIEC

)



print(

    "Ocena:",

    PLIK_OCENA

)



print(

    "Predykcje:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    )

)



print(

    "Historia:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    )

)
# =====================================================
# LABORATORIUM V2
# ANALIZA PAMIĘCI + PEWNOŚCI + KLAS + PREDYKCJI
# FRAGMENT 1/2
# =====================================================


import os
import json
import pandas as pd
import numpy as np

from datetime import datetime



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = (
    r"modele_kursy_przygotowane"
    r"\siec_01_start_kursow"
)


NAZWA_BAZY = "kursy_przygotowane"


NAZWA_MODELU = os.path.basename(
    KATALOG_MODELU
)



# =====================================================
# LABORATORIUM
# =====================================================


KATALOG_LABORATORIUM = os.path.join(
    "laboratorium",
    NAZWA_BAZY,
    NAZWA_MODELU
)



os.makedirs(
    KATALOG_LABORATORIUM,
    exist_ok=True
)



# =====================================================
# PLIKI WEJŚCIOWE
# =====================================================


PLIK_KLASY = os.path.join(
    KATALOG_MODELU,
    "klasy.json"
)



PLIK_PRED_WYNIK = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_z_wynikiem.csv"
)



PLIK_PRED_GRUPY = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_grupy.csv"
)



PLIK_OCENA = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "ocena.json"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "pamiec_obserwacji.json"
)




# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(
    PLIK_KLASY,
    encoding="utf-8"
) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v):k

    for k,v in klasy.items()

}



print(
    "Załadowano klas:",
    len(ID_NA_WYNIK)
)



# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


df_historia = pd.read_csv(

    PLIK_PRED_WYNIK,

    sep=";",

    encoding="utf-8"

)



print(
    "Historia:",
    len(df_historia)
)



# =====================================================
# WCZYTANIE AKTUALNYCH PREDYKCJI
# =====================================================


df_predykcja = pd.read_csv(

    PLIK_PRED_GRUPY,

    sep=";",

    encoding="utf-8"

)



print(
    "Aktualne predykcje:",
    len(df_predykcja)
)



# =====================================================
# WCZYTANIE OCENY MODELU
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:

        ocena_modelu = json.load(f)


else:


    ocena_modelu = {}




# =====================================================
# WCZYTANIE PAMIĘCI OBSERWACJI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:

        pamiec_obserwacji = json.load(f)


else:


    pamiec_obserwacji = {}




print(
    "Pamięć obserwacji:",
    len(pamiec_obserwacji)
)




# =====================================================
# ANALIZA KLAS
# =====================================================


analiza_klas = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    ilosc = len(dane)



    if ilosc == 0:


        analiza_klas[str(id_grupy)] = {


            "wynik":

            wynik,


            "ilosc_predykcji":

            0,


            "trafienia":

            0,


            "skutecznosc":

            0,


            "rzeczywisty_rozkład":

            {}

        }


        continue




    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()




    rozklad = (

        dane["wynik_rzeczywisty"]

        .value_counts(normalize=True)

        .to_dict()

    )




    analiza_klas[str(id_grupy)] = {


        "wynik":

        wynik,


        "ilosc_predykcji":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        ),



        "rzeczywisty_rozkład":

        rozklad

    }




# =====================================================
# ANALIZA PEWNOŚCI DYNAMICZNA
# =====================================================


analiza_pewnosci = {}




df_historia = df_historia.sort_values(
    "pewnosc"
)




# 10 równych grup według ilości danych

df_historia["koszyk_pewnosci"] = pd.qcut(

    df_historia["pewnosc"],

    q=10,

    duplicates="drop"

)




for koszyk, dane in df_historia.groupby(

    "koszyk_pewnosci",

    observed=True

):


    ilosc = len(dane)



    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()



    analiza_pewnosci[str(koszyk)] = {


        "ilosc":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        )

    }




# =====================================================
# ANALIZA PEWNOŚCI DLA KAŻDEJ KLASY
# =====================================================


analiza_pewnosci_klasy = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane_klasy = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    if len(dane_klasy) == 0:

        continue




    dane_klasy = dane_klasy.copy()



    dane_klasy["koszyk"] = pd.qcut(

        dane_klasy["pewnosc"],

        q=10,

        duplicates="drop"

    )



    koszyki = {}



    for koszyk,dane in dane_klasy.groupby(

        "koszyk",

        observed=True

    ):



        ilosc = len(dane)



        trafienia = (

            dane["wynik_predykcji"]

            ==

            dane["wynik_rzeczywisty"]

        ).sum()



        koszyki[str(koszyk)] = {


            "ilosc":

            int(ilosc),


            "trafienia":

            int(trafienia),


            "skutecznosc":

            float(

                trafienia / ilosc

            )

        }




    analiza_pewnosci_klasy[str(id_grupy)] = {


        "wynik":

        wynik,


        "progi_pewnosci":

        koszyki

    }




# KONIEC FRAGMENTU 1/2# # -*- coding: utf-8 -*-

import csv
import math
import statistics
import os
import sys


csv.field_size_limit(sys.maxsize)



def normalize(value, min_val, max_val):

    if max_val - min_val == 0:
        return 0.5

    return max(
        0,
        min(
            1,
            (value - min_val) / (max_val - min_val)
        )
    )



def bezpieczny_log(value):

    return math.log(
        max(value, 1.01)
    )



def oblicz_cechy_3kursy_rozszerzone(bloki):


    kurs_1 = [b[0] for b in bloki]
    kurs_X = [b[1] for b in bloki]
    kurs_2 = [b[2] for b in bloki]
    czasy = [b[3] for b in bloki]


    start_1 = kurs_1[0]
    start_X = kurs_X[0]
    start_2 = kurs_2[0]


    koniec_1 = kurs_1[-1]
    koniec_X = kurs_X[-1]
    koniec_2 = kurs_2[-1]



    zmiana_1 = ((start_1-koniec_1)/start_1)*100 if start_1 else 0
    zmiana_X = ((start_X-koniec_X)/start_X)*100 if start_X else 0
    zmiana_2 = ((start_2-koniec_2)/start_2)*100 if start_2 else 0



    amplituda_1 = ((max(kurs_1)-min(kurs_1))/start_1)*100 if start_1 else 0
    amplituda_X = ((max(kurs_X)-min(kurs_X))/start_X)*100 if start_X else 0
    amplituda_2 = ((max(kurs_2)-min(kurs_2))/start_2)*100 if start_2 else 0



    czas_trwania = max(czasy)-min(czasy)

    czas_h = czas_trwania / 3600 if czas_trwania else 0



    tempo_1 = zmiana_1/czas_h if czas_h else 0
    tempo_X = zmiana_X/czas_h if czas_h else 0
    tempo_2 = zmiana_2/czas_h if czas_h else 0



    synchronizacja = 1 if (

        (zmiana_1 > 0 and zmiana_X > 0 and zmiana_2 > 0)

        or

        (zmiana_1 < 0 and zmiana_X < 0 and zmiana_2 < 0)

    ) else 0



    max_wahanie_1 = max(
        abs(kurs_1[i+1]-kurs_1[i])
        for i in range(len(kurs_1)-1)
    )


    max_wahanie_X = max(
        abs(kurs_X[i+1]-kurs_X[i])
        for i in range(len(kurs_X)-1)
    )


    max_wahanie_2 = max(
        abs(kurs_2[i+1]-kurs_2[i])
        for i in range(len(kurs_2)-1)
    )



    log_min = math.log(1.01)
    log_max = math.log(10)



    log_start_1 = normalize(
        bezpieczny_log(start_1),
        log_min,
        log_max
    )

    log_start_X = normalize(
        bezpieczny_log(start_X),
        log_min,
        log_max
    )

    log_start_2 = normalize(
        bezpieczny_log(start_2),
        log_min,
        log_max
    )


    log_koniec_1 = normalize(
        bezpieczny_log(koniec_1),
        log_min,
        log_max
    )

    log_koniec_X = normalize(
        bezpieczny_log(koniec_X),
        log_min,
        log_max
    )

    log_koniec_2 = normalize(
        bezpieczny_log(koniec_2),
        log_min,
        log_max
    )



    ratio_1X_start = start_1/start_X if start_X else 1
    ratio_1_2_start = start_1/start_2 if start_2 else 1
    ratio_X2_start = start_X/start_2 if start_2 else 1


    ratio_1X_koniec = koniec_1/koniec_X if koniec_X else 1
    ratio_1_2_koniec = koniec_1/koniec_2 if koniec_2 else 1
    ratio_X2_koniec = koniec_X/koniec_2 if koniec_2 else 1



    stat_mean = [
        statistics.mean(kurs_1),
        statistics.mean(kurs_X),
        statistics.mean(kurs_2)
    ]


    stat_median = [
        statistics.median(kurs_1),
        statistics.median(kurs_X),
        statistics.median(kurs_2)
    ]


    stat_stdev = [

        statistics.stdev(kurs_1)
        if len(kurs_1)>1 else 0,

        statistics.stdev(kurs_X)
        if len(kurs_X)>1 else 0,

        statistics.stdev(kurs_2)
        if len(kurs_2)>1 else 0

    ]



    return [

        normalize(zmiana_1,-100,100),
        normalize(zmiana_X,-100,100),
        normalize(zmiana_2,-100,100),

        normalize(amplituda_1,0,100),
        normalize(amplituda_X,0,100),
        normalize(amplituda_2,0,100),

        normalize(tempo_1,-50,50),
        normalize(tempo_X,-50,50),
        normalize(tempo_2,-50,50),

        synchronizacja,

        max_wahanie_1,
        max_wahanie_X,
        max_wahanie_2,

        normalize(start_1,1.01,10),
        normalize(start_X,1.01,10),
        normalize(start_2,1.01,10),

        normalize(koniec_1,1.01,10),
        normalize(koniec_X,1.01,10),
        normalize(koniec_2,1.01,10),

        log_start_1,
        log_start_X,
        log_start_2,

        log_koniec_1,
        log_koniec_X,
        log_koniec_2,

        normalize(ratio_1X_start,0,10),
        normalize(ratio_1_2_start,0,10),
        normalize(ratio_X2_start,0,10),

        normalize(ratio_1X_koniec,0,10),
        normalize(ratio_1_2_koniec,0,10),
        normalize(ratio_X2_koniec,0,10),

        normalize(stat_mean[0],1,10),
        normalize(stat_mean[1],1,10),
        normalize(stat_mean[2],1,10),

        normalize(stat_median[0],1,10),
        normalize(stat_median[1],1,10),
        normalize(stat_median[2],1,10),

        normalize(stat_stdev[0],0,5),
        normalize(stat_stdev[1],0,5),
        normalize(stat_stdev[2],0,5),

        czas_h
    ]



def przetworz_plik_3kursy_rozszerzone(
        nazwa_pliku,
        nazwa_wyjsciowa
):


    if not os.path.exists(nazwa_pliku):

        print(
            "Brak pliku:",
            nazwa_pliku
        )

        return



    zapisano = 0
    pominieto = 0



    try:

        with open(
            nazwa_pliku,
            "r",
            encoding="utf-8-sig",
            newline=""
        ) as f, open(
            nazwa_wyjsciowa,
            "w",
            encoding="utf-8",
            newline=""
        ) as out:


            reader = csv.reader(
                f,
                delimiter=";"
            )


            writer = csv.writer(
                out,
                delimiter=";"
            )



            writer.writerow(
                [
                    "id_meczu",
                    "zmiana_1","zmiana_X","zmiana_2",
                    "amplituda_1","amplituda_X","amplituda_2",
                    "tempo_1","tempo_X","tempo_2",
                    "synchronizacja",
                    "max_wahanie_1","max_wahanie_X","max_wahanie_2",
                    "start_1_raw","start_X_raw","start_2_raw",
                    "koniec_1_raw","koniec_X_raw","koniec_2_raw",
                    "log_start_1","log_start_X","log_start_2",
                    "log_koniec_1","log_koniec_X","log_koniec_2",
                    "ratio_1X_start","ratio_1_2_start","ratio_X2_start",
                    "ratio_1X_koniec","ratio_1_2_koniec","ratio_X2_koniec",
                    "mean_1","mean_X","mean_2",
                    "median_1","median_X","median_2",
                    "stdev_1","stdev_X","stdev_2",
                    "czas_h"
                ]
            )



            for row in reader:


                if len(row)<7:

                    pominieto += 1
                    continue



                mecz = row[2]

                bloki = []



                for i in range(3,len(row),4):

                    try:

                        k1 = float(row[i])
                        kX = float(row[i+1])
                        k2 = float(row[i+2])

                        # poprawka dla starych i nowych danych
                        czas = float(row[i+3])


                        bloki.append(
                            (
                                k1,
                                kX,
                                k2,
                                czas
                            )
                        )


                    except (ValueError,IndexError):

                        continue



                if len(bloki)<2:

                    pominieto += 1
                    continue



                cechy = oblicz_cechy_3kursy_rozszerzone(
                    bloki
                )


                writer.writerow(
                    [
                        mecz
                    ]
                    +
                    [
                        round(x,5)
                        for x in cechy
                    ]
                )


                zapisano += 1



                if zapisano % 10000 == 0:

                    print(
                        "Zapisano:",
                        zapisano
                    )



        print("===================")
        print("Gotowe")
        print("Zapisano:", zapisano)
        print("Pominięto:", pominieto)
        print("Plik:", nazwa_wyjsciowa)



    except Exception as e:

        print(
            "Błąd:",
            e
        )



# ================================
# START
# ================================


pliki = [

    (
        "./dane/database_popularne_dzisiaj.csv",
        "./dane/dataBase_futbol_popularne_trend.csv"
    ),
    
    (
        "./dane/database_dzisiaj.csv",
        "./dane/dataBase_futbol_trend.csv"
    )

]



for plik_in, plik_out in pliki:

    przetworz_plik_3kursy_rozszerzone(
        plik_in,
        plik_out
    )


import csv
import sys
import pandas as pd


# ==========================================
# Zwiększenie limitu wielkości pola CSV
# (duże rekordy z historią kursów)
# ==========================================

csv.field_size_limit(sys.maxsize)



# ==========================================
# PLIKI
# ==========================================

plik_wej = "./dane/database_popularne_dzisiaj.csv"

plik_wyj = "./dane/kursy_popularne_przygotowane.csv"



# ==========================================
# ODCZYT PLIKU
# ==========================================

wyniki = []


with open(
    plik_wej,
    "r",
    encoding="utf-8",
    newline="",
    errors="ignore"
) as f:


    reader = csv.reader(
        f,
        delimiter=";"
    )


    for nr, row in enumerate(reader):


        try:


            # pomijanie pustych lub uszkodzonych wierszy

            if len(row) < 8:
                continue



            # ==================================
            # STRUKTURA DANYCH
            # ==================================

            # indeks 2 - nazwa meczu

            mecz = row[2]



            # kursy początkowe

            kurs_1_start = row[3]

            kurs_X_start = row[4]

            kurs_2_start = row[5]



            # kursy końcowe
            # ostatnie wartości:
            #
            # row[-1]  = czas Unix
            # row[-2]  = kurs 2
            # row[-3]  = kurs X
            # row[-4]  = kurs 1


            kurs_2_koniec = row[-2]

            kurs_X_koniec = row[-3]

            kurs_1_koniec = row[-4]



            wyniki.append(

                {

                    "mecz": mecz,

                    "kurs_1_start": kurs_1_start,

                    "kurs_X_start": kurs_X_start,

                    "kurs_2_start": kurs_2_start,

                    "kurs_1_koniec": kurs_1_koniec,

                    "kurs_X_koniec": kurs_X_koniec,

                    "kurs_2_koniec": kurs_2_koniec

                }

            )



        except Exception as e:


            print(
                "Błąd w wierszu:",
                nr,
                e
            )



# ==========================================
# DATAFRAME
# ==========================================


df = pd.DataFrame(
    wyniki
)



# ==========================================
# Zamiana kursów na liczby
# ==========================================


kolumny_kursow = [

    "kurs_1_start",

    "kurs_X_start",

    "kurs_2_start",

    "kurs_1_koniec",

    "kurs_X_koniec",

    "kurs_2_koniec"

]



for kol in kolumny_kursow:


    df[kol] = pd.to_numeric(

        df[kol],

        errors="coerce"

    )



# ==========================================
# ZMIANY KURSÓW
# ==========================================


df["zmiana_kurs_1"] = (

    df["kurs_1_koniec"]

    -

    df["kurs_1_start"]

)



df["zmiana_kurs_X"] = (

    df["kurs_X_koniec"]

    -

    df["kurs_X_start"]

)



df["zmiana_kurs_2"] = (

    df["kurs_2_koniec"]

    -

    df["kurs_2_start"]

)



# ==========================================
# PROCENTOWA ZMIANA KURSÓW
# ==========================================


df["procent_kurs_1"] = (

    df["zmiana_kurs_1"]

    /

    df["kurs_1_start"]

)



df["procent_kurs_X"] = (

    df["zmiana_kurs_X"]

    /

    df["kurs_X_start"]

)



df["procent_kurs_2"] = (

    df["zmiana_kurs_2"]

    /

    df["kurs_2_start"]

)



# ==========================================
# ZAPIS
# ==========================================


df.to_csv(

    plik_wyj,

    sep=";",

    index=False,

    encoding="utf-8"

)



# ==========================================
# PODSUMOWANIE
# ==========================================


print()

print("==============================")

print("KONIEC")

print("==============================")

print()

print(
    "Liczba meczów:",
    len(df)
)

print()

print(
    "Zapisano:",
    plik_wyj
)

print()

print(
    df.head()
)


