# -*- coding: utf-8 -*-

import csv
import sys


# zwiększenie limitu pojedynczego pola CSV
csv.field_size_limit(sys.maxsize)



# ==========================================
# KLASYFIKACJA KURSÓW
# ==========================================

def classify_odds(odds):

    levels = []


    for odd in odds:

        if odd < 1.2:
            level = 'poziom1'

        elif 1.2 <= odd < 1.4:
            level = 'poziom2'

        elif 1.4 <= odd < 1.6:
            level = 'poziom3'

        elif 1.6 <= odd < 1.8:
            level = 'poziom4'

        elif 1.8 <= odd < 2.0:
            level = 'poziom5'

        elif 2.0 <= odd < 2.2:
            level = 'poziom6'

        elif 2.2 <= odd < 2.4:
            level = 'poziom7'

        elif 2.4 <= odd < 2.6:
            level = 'poziom8'

        elif 2.6 <= odd < 2.8:
            level = 'poziom9'

        elif 2.8 <= odd < 3.0:
            level = 'poziom10'

        elif 3.0 <= odd < 3.2:
            level = 'poziom11'

        elif 3.2 <= odd < 3.4:
            level = 'poziom12'

        elif 3.4 <= odd < 3.6:
            level = 'poziom13'

        elif 3.6 <= odd < 3.8:
            level = 'poziom14'

        elif 3.8 <= odd < 4.0:
            level = 'poziom15'

        elif 4.0 <= odd < 4.2:
            level = 'poziom16'

        elif 4.2 <= odd < 4.4:
            level = 'poziom17'

        elif 4.4 <= odd < 4.6:
            level = 'poziom18'

        elif 4.6 <= odd < 4.8:
            level = 'poziom19'

        elif 4.8 <= odd < 5.0:
            level = 'poziom20'

        elif 5.0 <= odd < 5.2:
            level = 'poziom21'

        elif 5.2 <= odd < 5.4:
            level = 'poziom22'

        elif 5.4 <= odd < 5.6:
            level = 'poziom23'

        elif 5.6 <= odd < 5.8:
            level = 'poziom24'

        elif 5.8 <= odd < 6.0:
            level = 'poziom25'

        elif 6.0 <= odd < 6.2:
            level = 'poziom26'

        elif 6.2 <= odd < 6.4:
            level = 'poziom27'

        elif 6.4 <= odd < 6.6:
            level = 'poziom28'

        elif 6.6 <= odd < 6.8:
            level = 'poziom29'

        else:
            level = 'poziom30'


        levels.append(level)


    return levels



# ==========================================
# PRZETWARZANIE DUŻEGO CSV
# ==========================================

def process_and_save_data(
        input_file_path,
        output_file_path
):


    licznik = 0


    with open(
        input_file_path,
        'r',
        encoding='utf-8',
        newline=''
    ) as input_file, open(
        output_file_path,
        'w',
        encoding='utf-8',
        newline=''
    ) as output_file:


        reader = csv.reader(
            input_file,
            delimiter=';'
        )


        writer = csv.writer(
            output_file,
            delimiter=';'
        )


        writer.writerow(
            [
                'Mecz',
                'Poziomy'
            ]
        )


        for row in reader:


            if len(row) < 6:

                continue



            try:

                match_name = row[2]

                home_odds = float(
                    row[3]
                )

                draw_odds = float(
                    row[4]
                )

                away_odds = float(
                    row[5]
                )


            except:

                continue



            home_level = classify_odds(
                [home_odds]
            )


            draw_level = classify_odds(
                [draw_odds]
            )


            away_level = classify_odds(
                [away_odds]
            )


            combined_levels = (
                ''.join(home_level)
                +
                ''.join(draw_level)
                +
                ''.join(away_level)
            )



            writer.writerow(
                [
                    match_name,
                    combined_levels
                ]
            )


            licznik += 1



            if licznik % 10000 == 0:

                print(
                    "Przetworzono:",
                    licznik
                )



    print()
    print(
        "Zakończono."
    )

    print(
        "Liczba rekordów:",
        licznik
    )

    print(
        "Plik:",
        output_file_path
    )





# ==========================================
# START
# ==========================================


input_file_path = (
    './dane/'
    'database_Popularne_dzisiaj.csv'
)


output_file_path = (
    './dane/'
    'analizaKursowDni_dataBase_futbol_Popularne.csv'
)



process_and_save_data(
    input_file_path,
    output_file_path
)




