import pandas as pd
import numpy as np
import csv
import math

from sklearn.ensemble import RandomForestClassifier
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    accuracy_score
)


# =================================================
# PLIKI
# =================================================

plik_dane = "./dane/dopasowane_trendy_historyczne.csv"

plik_wagi = "./dane/wagi_dopasowania.csv"


plik_korelacja = "./dane/analiza_korelacji_cech.csv"

plik_rf = "./dane/random_forest_waznosc_cech.csv"

plik_ranking = "./dane/ranking_cech.csv"

plik_syntetyczne = "./dane/syntetyczne_trendy_historyczne.csv"

plik_poisson = "./dane/analiza_poisson_dixon.csv"



# =================================================
# PARAMETRY
# =================================================

LICZBA_SYNTH = 3

KROK = 0.02

MAX_GOLE = 8

RHO_DIXON = -0.1



# =================================================
# WCZYTANIE
# =================================================


df = pd.read_csv(
    plik_dane,
    sep=";"
)


df_wagi = pd.read_csv(
    plik_wagi,
    sep=";"
)



print(
    "Dane:",
    len(df)
)



# =================================================
# DODANIE WAG
# =================================================


df = df.merge(

    df_wagi,

    on="id_meczu_predykcja",

    how="left"

)


df["liczba_dopasowanych"] = (

    df["liczba_dopasowanych"]

    .fillna(1)

)



# =================================================
# ANALIZA WYNIKU
# =================================================


def rozbij_wynik(x):

    try:

        a,b = x.split(":")

        return int(a), int(b)


    except:

        return 0,0



def wynik_1x2(x):

    a,b = rozbij_wynik(x)


    if a>b:

        return 1


    elif a==b:

        return 0


    else:

        return 2



def wynik_gole(x):

    a,b = rozbij_wynik(x)

    return a+b




df["gole_dom"] = df["wynik"].apply(

    lambda x:
    rozbij_wynik(x)[0]

)


df["gole_wyj"] = df["wynik"].apply(

    lambda x:
    rozbij_wynik(x)[1]

)



df["gole"] = df["wynik"].apply(

    wynik_gole

)



df["klasa"] = df["wynik"].apply(

    wynik_1x2

)



# =================================================
# FUNKCJE POISSON
# =================================================


def poisson(k, lam):

    if lam <= 0:

        return 0


    try:

        return (

            math.exp(-lam)

            *

            (lam ** k)

            /

            math.factorial(k)

        )


    except:

        return 0




# =================================================
# DIXON COLES
# =================================================


def dixon_coles(

        gole_dom,

        gole_wyj,

        lambda_dom,

        lambda_wyj,

        rho=RHO_DIXON

):


    korekta = 1



    if gole_dom == 0 and gole_wyj == 0:


        korekta = (

            1

            -

            lambda_dom

            *

            lambda_wyj

            *

            rho

        )



    elif gole_dom == 1 and gole_wyj == 0:


        korekta = (

            1

            +

            lambda_wyj

            *

            rho

        )



    elif gole_dom == 0 and gole_wyj == 1:


        korekta = (

            1

            +

            lambda_dom

            *

            rho

        )



    elif gole_dom == 1 and gole_wyj == 1:


        korekta = (

            1

            -

            rho

        )



    return max(

        korekta,

        0

    )



# =================================================
# ŚREDNIE BRAMKI
# =================================================


srednia_dom = (

    df["gole_dom"]

    .mean()

)


srednia_wyj = (

    df["gole_wyj"]

    .mean()

)



print(
    "Średnia gole dom:",
    srednia_dom
)


print(
    "Średnia gole wyjazd:",
    srednia_wyj
)



# =================================================
# POISSON + DIXON COLES
# =================================================


def policz_dc(row):


    gd = row["gole_dom"]

    gw = row["gole_wyj"]



    p_dom = poisson(

        gd,

        srednia_dom

    )



    p_wyj = poisson(

        gw,

        srednia_wyj

    )



    dc = dixon_coles(

        gd,

        gw,

        srednia_dom,

        srednia_wyj

    )



    return (

        p_dom

        *

        p_wyj

        *

        dc

    )




df["prawdopodobienstwo_dc"] = df.apply(

    policz_dc,

    axis=1

)



print(
    "Poisson + Dixon-Coles gotowy"
)

# =================================================
# ZAPIS ANALIZY POISSON + DIXON COLES
# =================================================


df_poisson = df[

    [

        "id_meczu_predykcja",

        "wynik",

        "gole_dom",

        "gole_wyj",

        "gole",

        "prawdopodobienstwo_dc"

    ]

]


df_poisson.to_csv(

    plik_poisson,

    sep=";",

    index=False,

    encoding="utf-8"

)



print(
    "Analiza Poisson Dixon zapisana"
)



# =================================================
# PRZYGOTOWANIE CECH
# =================================================


usun = [

    "id_meczu_predykcja",

    "id_meczu",

    "wynik",

    "klasa",

    "gole",

    "gole_dom",

    "gole_wyj",

    "prawdopodobienstwo_dc"

]



X = df.drop(

    columns=usun,

    errors="ignore"

)



X = X.apply(

    pd.to_numeric,

    errors="coerce"

)



X = X.fillna(0)



# =================================================
# CEL MODELU
# =================================================
# gole ważone prawdopodobieństwem
# wynik bardziej realistyczny według modelu


df["wynik_modelowy"] = (

    df["gole"]

    *

    df["prawdopodobienstwo_dc"]

)



# =================================================
# KORELACJA POISSON + DIXON
# =================================================


wyniki_korelacji = []



for cecha in X.columns:


    try:


        korelacja = X[cecha].corr(

            df["wynik_modelowy"]

        )


    except:


        korelacja = 0



    wyniki_korelacji.append(

        {


            "cecha": cecha,


            "korelacja_dc": korelacja


        }

    )



df_kor = pd.DataFrame(

    wyniki_korelacji

)



df_kor.to_csv(

    plik_korelacja,

    sep=";",

    index=False,

    encoding="utf-8"

)



print(
    "Korelacja Poisson+Dixon gotowa"
)



# =================================================
# RANDOM FOREST CLASSIFIER
# =================================================


X_train, X_test, y_train, y_test = train_test_split(

    X,

    df["klasa"],

    test_size=0.2,

    random_state=42

)



rf = RandomForestClassifier(

    n_estimators=300,

    random_state=42,

    class_weight="balanced"

)



rf.fit(

    X_train,

    y_train

)



pred = rf.predict(

    X_test

)



print(

    "RF accuracy:",

    accuracy_score(

        y_test,

        pred

    )

)



# =================================================
# WAŻNOŚĆ CECH RF
# =================================================


df_rf = pd.DataFrame(

    {


        "cecha": X.columns,


        "RF": rf.feature_importances_


    }

)



df_rf.to_csv(

    plik_rf,

    sep=";",

    index=False,

    encoding="utf-8"

)



print(
    "Random Forest ważność cech gotowa"
)

# =================================================
# POŁĄCZENIE KORELACJI + RANDOM FOREST + DIXON
# =================================================


ranking = df_kor.merge(

    df_rf,

    on="cecha",

    how="inner"

)



# średnia wiarygodność wyników
# według Poisson + Dixon-Coles


srednia_dc = (

    df["prawdopodobienstwo_dc"]

    .mean()

)



ranking["DC"] = srednia_dc



# końcowa siła cechy


ranking["sila"] = (

    abs(

        ranking["korelacja_dc"]

    )

    *

    ranking["RF"]

    *

    ranking["DC"]

)



ranking = ranking.sort_values(

    "sila",

    ascending=False

)



ranking.to_csv(

    plik_ranking,

    sep=";",

    index=False,

    encoding="utf-8"

)



print(
    "Ranking cech gotowy"
)



# =================================================
# NAJLEPSZE CECHY DO SYNTEZY
# =================================================


najlepsze = dict(

    zip(

        ranking["cecha"],

        ranking["korelacja_dc"]

    )

)



# =================================================
# GENEROWANIE DANYCH SYNTHETYCZNYCH
# =================================================


with open(

    plik_syntetyczne,

    "w",

    encoding="utf-8",

    newline=""

) as f:



    writer = csv.writer(

        f,

        delimiter=";"

    )



    writer.writerow(

        [

            "typ_danych"

        ]

        +

        list(df.columns)

    )



    for _, row in df.iterrows():



        # ---------------------------------
        # ORYGINAŁ
        # ---------------------------------


        writer.writerow(

            [

                "oryginal"

            ]

            +

            list(row)

        )



        # ---------------------------------
        # SYNTH
        # ---------------------------------


        for nr in range(

            1,

            LICZBA_SYNTH + 1

        ):



            nowy = row.copy()



            for cecha, korelacja in najlepsze.items():



                if cecha not in nowy:

                    continue



                try:


                    wartosc = float(

                        nowy[cecha]

                    )


                except:


                    continue



                if korelacja > 0:


                    wartosc += (

                        KROK

                        *

                        nr

                    )



                elif korelacja < 0:


                    wartosc -= (

                        KROK

                        *

                        nr

                    )



                nowy[cecha] = wartosc



            writer.writerow(

                [

                    f"syntetyczny_{nr}"

                ]

                +

                list(nowy)

            )



print(
    "Dane syntetyczne gotowe"
)



# =================================================
# PODSUMOWANIE
# =================================================


print()

