print(
    "Załadowano rekordów trend:",
    len(BAZA_TREND)
)



# ==========================================================
# NAGŁÓWEK ŹRÓDŁOWY
# ==========================================================

HEADER_TREND = [

"id_meczu",
"zmiana_1",
"zmiana_X",
"zmiana_2",
"amplituda_1",
"amplituda_X",
"amplituda_2",
"tempo_1",
"tempo_X",
"tempo_2",
"synchronizacja",
"max_wahanie_1",
"max_wahanie_X",
"max_wahanie_2",
"start_1_raw",
"start_X_raw",
"start_2_raw",
"koniec_1_raw",
"koniec_X_raw",
"koniec_2_raw",
"log_start_1",
"log_start_X",
"log_start_2",
"log_koniec_1",
"log_koniec_X",
"log_koniec_2",
"ratio_1X_start",
"ratio_1_2_start",
"ratio_X2_start",
"ratio_1X_koniec",
"ratio_1_2_koniec",
"ratio_X2_koniec",
"mean_1",
"mean_X",
"mean_2",
"median_1",
"median_X",
"median_2",
"stdev_1",
"stdev_X",
"stdev_2",
"czas_h",
"wynik"

]



# ==========================================================
# ANALIZA MECZÓW
# ==========================================================

WYNIKI = []


with open(
    PLIK_GRUPY,
    "r",
    encoding="utf-8"
) as plik:


    reader = csv.reader(
        plik,
        delimiter=";"
    )


    for row in reader:


        if len(row) < 2:
            continue



        id_meczu_predykcja = row[0].strip()

        grupa = row[1].strip()



        if grupa not in TAGS_WORLD_MAP:


            print(
                "Brak grupy:",
                grupa
            )

            continue



        historia = TAGS_WORLD_MAP[grupa]



        DOPASOWANE = []



        # --------------------------------------
        # Szukanie faktycznych dopasowań
        # --------------------------------------

        for rekord in historia:


            id_historyczny = rekord["mecz"].strip()



            if id_historyczny in BAZA_TREND:


                dane = BAZA_TREND[id_historyczny]


                DOPASOWANE.append(
                    [
                        id_meczu_predykcja,
                        id_historyczny,
                        *dane[1:]
                    ]
                )



        ilosc_dopasowan = len(
            DOPASOWANE
        )



        # dodanie licznika

        for rekord in DOPASOWANE:


            rekord.insert(
                1,
                ilosc_dopasowan
            )


            WYNIKI.append(
                rekord
            )



# ==========================================================
# ZAPIS CSV
# ==========================================================

with open(
    PLIK_WYNIK,
    "w",
    encoding="utf-8",
    newline=""
) as plik:


    writer = csv.writer(
        plik,
        delimiter=";"
    )


    writer.writerow(

        [

        "id_meczu_predykcja",
        "ilosc_dopsowan",

        *HEADER_TREND

        ]

    )


    writer.writerows(
        WYNIKI
    )



# ==========================================================
# PODSUMOWANIE
# ==========================================================

