# ============================================================
# DEFINICJA WYNIKÓW NAJBARDZIEJ ISTOTNYCH
# ============================================================


WYNIKI_DOM = [

    "1:0",

    "2:0",

    "3:0",

    "2:1",

    "3:1",

    "3:2"

]





WYNIKI_WYJAZD = [

    "0:1",

    "0:2",

    "0:3",

    "1:2",

    "1:3",

    "2:3"

]





WYNIKI_REMIS = [

    "0:0",

    "1:1",

    "2:2"

]





WYNIKI_ANALIZOWANE = (

    WYNIKI_DOM

    +

    WYNIKI_WYJAZD

    +

    WYNIKI_REMIS

)







# ============================================================
# WCZYTANIE MAPY GRUP
# ============================================================


GRUPY = {}





with open(

    PLIK_GRUP,

    "r",

    encoding="utf-8"

) as plik:


    reader = csv.reader(

        plik,

        delimiter=";"

    )



    for row in reader:


        if len(row) < 2:

            continue




        grupa = row[0].strip()



        wyniki = []



        for element in row[1:]:


            element = element.strip()



            if ";" in element:


                wyniki.extend(

                    element.split(";")

                )

            else:


                wyniki.append(

                    element

                )






        poprawne = []



        for wynik in wyniki:


            try:


                dom, wyjazd = wynik.split(":")


                int(dom)

                int(wyjazd)



                poprawne.append(

                    wynik

                )


            except:


                pass






        GRUPY[grupa] = poprawne







print(

    "Załadowano grup:",

    len(GRUPY)

)








# ============================================================
# OKREŚLENIE TYPU MECZU
# ============================================================


def typ_wyniku(wynik):


    try:


        dom, wyjazd = wynik.split(":")


        dom = int(dom)

        wyjazd = int(wyjazd)



        if dom > wyjazd:


            return "1"



        elif dom == wyjazd:


            return "X"



        else:


            return "2"



    except:


        return None








# ============================================================
# KLASYFIKACJA WYNIKU
# ============================================================


def kategoria_wyniku(wynik):


    if wynik in WYNIKI_DOM:


        return "trafiony_wynik_gospodarze"




    elif wynik in WYNIKI_WYJAZD:


        return "trafiony_wynik_goscie"




    elif wynik in WYNIKI_REMIS:


        return "trafiony_wynik_remis"




    typ = typ_wyniku(wynik)



    if typ == "1":


        return "inne_wygrane_gospodarzy"



    elif typ == "2":


        return "inne_wygrane_gosci"



    elif typ == "X":


        return "inne_remisy"



    return "nieznany"








# ============================================================
# GŁÓWNY ANALIZATOR GRUPY
# ============================================================


def analiza_grupy(wyniki):


    ilosc = len(wyniki)



    if ilosc == 0:


        return {}




    licznik = Counter(

        wyniki

    )




    kategorie = Counter()



    for wynik in wyniki:


        kategorie[

            kategoria_wyniku(wynik)

        ] += 1







    wyniki_docelowe = {}



    for wynik in WYNIKI_ANALIZOWANE:


        wystapienia = licznik.get(

            wynik,

            0

        )


        wyniki_docelowe[wynik] = {


            "ilosc":

                wystapienia,


            "procent":

                round(

                    wystapienia

                    /

                    ilosc

                    *

                    100,

                    2

                )

        }






    profil = {


        "gospodarze":0,


        "remis":0,


        "goscie":0

    }




    gole_dom = 0


    gole_wyj = 0





    for wynik in wyniki:


        typ = typ_wyniku(wynik)



        if typ == "1":


            profil["gospodarze"] += 1



        elif typ == "X":


            profil["remis"] += 1



        elif typ == "2":


            profil["goscie"] += 1




        try:


            dom, wyj = wynik.split(":")


            gole_dom += int(dom)


            gole_wyj += int(wyj)



        except:


            pass





    for element in profil:


        profil[element] = {


            "ilosc":

                profil[element],


            "procent":

                round(

                    profil[element]

                    /

                    ilosc

                    *

                    100,

                    2

                )

        }







    return {


        "ilosc_przypadkow":

            ilosc,



        "wyniki_docelowe":

            wyniki_docelowe,



        "profil_meczu_1X2":

            profil,



        "statystyka_goli":{


            "srednia_gole_dom":

                round(

                    gole_dom / ilosc,

                    3

                ),



            "srednia_gole_wyj":

                round(

                    gole_wyj / ilosc,

                    3

                ),



            "srednia_goli_mecz":

                round(

                    (gole_dom + gole_wyj)

                    /

                    ilosc,

                    3

                )

        }

    }
# ============================================================
# FRAGMENT 2/2
#
# BUDOWA TRZECH WARSTW ŚWIATA
# I ZAPIS AKTUALNEJ WIEDZY
# ============================================================




# ============================================================
