# ============================================================


WORLD_LEVEL_1 = {}

WORLD_LEVEL_2 = {}

WORLD_FULL = {}







# ============================================================
# ROZBIJANIE NA POZIOMY
#
# przykład:
#
# poziom3poziom17poziom20
#
# wynik:
#
# [
#   poziom3,
#   poziom17,
#   poziom20
# ]
#
# ============================================================


def pobierz_poziomy(grupa):


    elementy = grupa.split(
        "poziom"
    )


    poziomy = []



    for element in elementy:


        element = element.strip()



        if element:


            poziomy.append(

                "poziom" + element

            )



    return poziomy







# ============================================================
# BUDOWA MAPY ŚWIATA
# ============================================================


for grupa, wyniki in GRUPY.items():


    poziomy = pobierz_poziomy(

        grupa

    )



    if len(poziomy) == 0:


        continue







    # ========================================================
    # POZIOM 1
    #
    # przykład:
    #
    # poziom3
    #
    # zbiera wszystkie:
    #
    # poziom3poziom17
    # poziom3poziom17poziom20
    #
    # ========================================================


    poziom_1 = poziomy[0]



    if poziom_1 not in WORLD_LEVEL_1:


        WORLD_LEVEL_1[poziom_1] = []



    WORLD_LEVEL_1[poziom_1].extend(

        wyniki

    )









    # ========================================================
    # POZIOM 2
    #
    # przykład:
    #
    # poziom3poziom17
    #
    # ========================================================


    if len(poziomy) >= 2:



        poziom_2 = (

            poziomy[0]

            +

            poziomy[1]

        )




        if poziom_2 not in WORLD_LEVEL_2:


            WORLD_LEVEL_2[poziom_2] = []



        WORLD_LEVEL_2[poziom_2].extend(

            wyniki

        )









    # ========================================================
    # PEŁNA GRUPA
    #
    # dokładny przypadek
    #
    # poziom3poziom17poziom20
    #
    # ========================================================


    WORLD_FULL[grupa] = wyniki







# ============================================================
# ANALIZA WARSTWY ŚWIATA
# ============================================================


def analizuj_warstwę(dane):


    wynik = {}



    for nazwa, historia in dane.items():



        wynik[nazwa] = {


            "poziom":

                nazwa,


            "analiza":

                analiza_grupy(

                    historia

                )

        }



    return wynik







