with open(

    os.path.join(
        KATALOG_MODELU,
        "metadata.json"
    ),

    encoding="utf-8"

) as f:

    metadata = json.load(f)



CECHY = metadata["cechy"]


NAZWA_MODELU = metadata["nazwa"]





# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "klasy.json"
    ),

    encoding="utf-8"

) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v): k

    for k,v in klasy.items()

}





# =====================================================
# WCZYTANIE AKTUALNEJ PREDYKCJI
# =====================================================


df_pred = pd.read_csv(

    PLIK_PREDYKCJI,

    sep=";",

    encoding="utf-8"

)



INDEX_MAP = {


    kolumna:index

    for index,kolumna

    in enumerate(df_pred.columns)

}



print("MAPA CECH")

print(INDEX_MAP)





# =====================================================
# CECHY MODELU
# =====================================================


INDEX_CECH = []



for cecha in CECHY:


    if cecha not in INDEX_MAP:


        raise Exception(

            f"Brak cechy modelu: {cecha}"

        )


    INDEX_CECH.append(

        INDEX_MAP[cecha]

    )



print(

    "Cechy modelu:",

    INDEX_CECH

)





# =====================================================
# AKTUALNE MECZE DO PREDYKCJI
# =====================================================


NAZWY_PREDYKCJI = (

    df_pred["id_meczu"]

    .astype(str)

    .tolist()

)



X_PREDYKCJA = df_pred.iloc[

    :,

    INDEX_CECH

]



X_PREDYKCJA = np.nan_to_num(

    X_PREDYKCJA.values

)





# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


hist = pd.read_csv(

    PLIK_HISTORIA,

    sep=";",

    header=None,

    encoding="utf-8"

)



NAZWY_HISTORIA = hist.iloc[:,0].astype(str)



