# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 1/2
# =====================================================


import os
import json
import pandas as pd
import numpy as np

from datetime import datetime

from tensorflow.keras.models import load_model



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = r"modele_dataBase_futbol_trend\siec_05_start_raw"


PLIK_PREDYKCJI = r"dane\dataBase_futbol_trend.csv"


PLIK_HISTORIA = r"dane\kod_dataBase_futbol_trend.csv"



KATALOG_OBSERWACJI = os.path.join(
    KATALOG_MODELU,
    "obserwacja"
)


KATALOG_PREDYKCJI = os.path.join(
    KATALOG_MODELU,
    "predykcje"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_OBSERWACJI,
    "pamiec_obserwacji.json"
)



PLIK_OCENA = os.path.join(
    KATALOG_OBSERWACJI,
    "ocena.json"
)



os.makedirs(
    KATALOG_OBSERWACJI,
    exist_ok=True
)



os.makedirs(
    KATALOG_PREDYKCJI,
    exist_ok=True
)





# =====================================================
# WCZYTANIE METADANYCH MODELU
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "metadata.json"
    ),

    encoding="utf-8"

) as f:

    metadata = json.load(f)



CECHY = metadata["cechy"]


NAZWA_MODELU = metadata["nazwa"]





# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(

    os.path.join(
        KATALOG_MODELU,
        "klasy.json"
    ),

    encoding="utf-8"

) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v): k

    for k,v in klasy.items()

}





# =====================================================
# WCZYTANIE AKTUALNEJ PREDYKCJI
# =====================================================


df_pred = pd.read_csv(

    PLIK_PREDYKCJI,

    sep=";",

    encoding="utf-8"

)



INDEX_MAP = {


    kolumna:index

    for index,kolumna

    in enumerate(df_pred.columns)

}



print("MAPA CECH")

print(INDEX_MAP)





# =====================================================
# CECHY MODELU
# =====================================================


INDEX_CECH = []



for cecha in CECHY:


    if cecha not in INDEX_MAP:


        raise Exception(

            f"Brak cechy modelu: {cecha}"

        )


    INDEX_CECH.append(

        INDEX_MAP[cecha]

    )



print(

    "Cechy modelu:",

    INDEX_CECH

)





# =====================================================
# AKTUALNE MECZE DO PREDYKCJI
# =====================================================


NAZWY_PREDYKCJI = (

    df_pred["id_meczu"]

    .astype(str)

    .tolist()

)



X_PREDYKCJA = df_pred.iloc[

    :,

    INDEX_CECH

]



X_PREDYKCJA = np.nan_to_num(

    X_PREDYKCJA.values

)





# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


hist = pd.read_csv(

    PLIK_HISTORIA,

    sep=";",

    header=None,

    encoding="utf-8"

)



NAZWY_HISTORIA = hist.iloc[:,0].astype(str)



X_HISTORIA = hist.iloc[

    :,

    INDEX_CECH

]



Y_HISTORIA = hist.iloc[:,-1]



X_HISTORIA = np.nan_to_num(

    X_HISTORIA.values

)





# =====================================================
# WCZYTANIE MODELU
# =====================================================


model = load_model(

    os.path.join(

        KATALOG_MODELU,

        "model.h5"

    )

)





# =====================================================
# PREDYKCJA HISTORII
# =====================================================


print(
    "Analiza historii..."
)



pred_hist = model.predict(

    X_HISTORIA

)



klasy_pred_hist = np.argmax(

    pred_hist,

    axis=1

)





# =====================================================
# PREDYKCJA AKTUALNYCH MECZÓW
# =====================================================


print(

    "Analiza aktualnych meczów..."

)



pred = model.predict(

    X_PREDYKCJA

)



klasy_pred = np.argmax(

    pred,

    axis=1

)





# =====================================================
# WCZYTANIE PAMIĘCI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:


        pamiec_obserwacji = json.load(f)



else:


    pamiec_obserwacji = {}





# =====================================================
# WCZYTANIE OCENY
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:


        ocena = json.load(f)



else:


    ocena = {


        "model":

        NAZWA_MODELU,


        "ocena_ogolna":

        {

            "ilosc":

            0,


            "trafienia":

            0

        },


        "ocena_wynikow":

        {}

    }





# =====================================================
# STRUKTURY SESJI
# =====================================================


czas = datetime.now().strftime(

    "%Y-%m-%d %H:%M:%S"

)



nowe_obserwacje = []


nowe_predykcje = []


nowa_historia = []




analiza = {}



for wynik in klasy.keys():


    analiza[wynik] = {


        "ilosc_wystapien":0,


        "trafienia":0,


        "bledy":{}

    }




print(

    "Przygotowano dane."

)
# =====================================================
# GENERATOR ANALIZY TRENDÓW + PAMIĘĆ OBSERWACJI
# CZĘŚĆ 2/2
# =====================================================



# =====================================================
# ANALIZA HISTORII Z WYNIKAMI
# =====================================================


for i,p in enumerate(klasy_pred_hist):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    real_wynik = str(
        Y_HISTORIA.iloc[i]
    )


    nazwa_meczu = str(
        NAZWY_HISTORIA.iloc[i]
    )


    pewnosc = float(
        np.max(pred_hist[i])
    )


    trafienie = (
        pred_wynik == real_wynik
    )



    obserwacja = {


        "data":

        czas,


        "model":

        NAZWA_MODELU,


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "predykcja":

        pred_wynik,


        "wynik_rzeczywisty":

        real_wynik,


        "pewnosc":

        pewnosc,


        "trafienie":

        trafienie

    }





    # =========================================
    # AKTUALIZACJA PAMIĘCI MECZU
    # =========================================


    if nazwa_meczu not in pamiec_obserwacji:


        pamiec_obserwacji[nazwa_meczu] = []



        obserwacja["pierwsza_obserwacja"] = True



    else:


        ostatnia = pamiec_obserwacji[nazwa_meczu][-1]



        if ostatnia["predykcja"] != pred_wynik:


            obserwacja["zmiana_predykcji"] = {


                "stara":

                ostatnia["predykcja"],


                "nowa":

                pred_wynik

            }



        if ostatnia["pewnosc"] != pewnosc:


            obserwacja["zmiana_pewnosci"] = {


                "stara":

                ostatnia["pewnosc"],


                "nowa":

                pewnosc

            }





    pamiec_obserwacji[nazwa_meczu].append(

        obserwacja

    )



    nowe_obserwacje.append(

        obserwacja

    )





    # statystyka klasy


    analiza[pred_wynik]["ilosc_wystapien"] += 1



    if trafienie:


        analiza[pred_wynik]["trafienia"] += 1


    else:


        if real_wynik not in analiza[pred_wynik]["bledy"]:


            analiza[pred_wynik]["bledy"][real_wynik] = 0



        analiza[pred_wynik]["bledy"][real_wynik] += 1







# =====================================================
# AKTUALNE MECZE BEZ WYNIKU
# =====================================================


for i,p in enumerate(klasy_pred):


    grupa = int(p)


    pred_wynik = ID_NA_WYNIK[grupa]


    nazwa_meczu = str(

        NAZWY_PREDYKCJI[i]

    )


    pewnosc = float(

        np.max(pred[i])

    )



    predykcja = {


        "id_meczu":

        nazwa_meczu,


        "id_grupy":

        grupa,


        "wynik_predykcji":

        pred_wynik,


        "pewnosc":

        pewnosc

    }



    nowe_predykcje.append(

        predykcja

    )







# =====================================================
# AKTUALIZACJA OCENY MODELU
# =====================================================


ilosc_globalna = 0

trafienia_globalne = 0



ocena_wynikow = {}



for wynik,dane in analiza.items():


    ilosc = dane["ilosc_wystapien"]


    trafienia = dane["trafienia"]



    ilosc_globalna += ilosc


    trafienia_globalne += trafienia



    ocena_wynikow[wynik] = {


        "ilosc_predykcji":

        ilosc,


        "trafienia":

        trafienia,


        "skutecznosc":

        (

            trafienia / ilosc

            if ilosc > 0

            else 0

        ),


        "bledy":

        dane["bledy"]

    }





ocena = {


    "model":

    NAZWA_MODELU,


    "data":

    czas,


    "ocena_ogolna":{


        "ilosc_meczow":

        ilosc_globalna,


        "trafienia":

        trafienia_globalne,


        "skutecznosc":

        (

            trafienia_globalne /

            ilosc_globalna

            if ilosc_globalna > 0

            else 0

        )

    },


    "ocena_wynikow":

    ocena_wynikow

}







# =====================================================
# ZAPIS PAMIĘCI
# =====================================================


with open(

    PLIK_PAMIEC,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        pamiec_obserwacji,

        f,

        indent=4,

        ensure_ascii=False

    )





# =====================================================
# ZAPIS OCENY
# =====================================================


with open(

    PLIK_OCENA,

    "w",

    encoding="utf-8"

) as f:


    json.dump(

        ocena,

        f,

        indent=4,

        ensure_ascii=False

    )







# =====================================================
# ZAPIS AKTUALNEJ PREDYKCJI
# =====================================================


pd.DataFrame(

    nowe_predykcje

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







# =====================================================
# ZAPIS HISTORII Z WYNIKAMI
# =====================================================


historia_csv = []



for mecz,lista in pamiec_obserwacji.items():


    ostatnia = lista[-1]


    historia_csv.append(


        {


            "id_meczu":

            mecz,


            "id_grupy":

            ostatnia["id_grupy"],


            "wynik_predykcji":

            ostatnia["predykcja"],


            "pewnosc":

            ostatnia["pewnosc"],


            "wynik_rzeczywisty":

            ostatnia["wynik_rzeczywisty"]

        }

    )







pd.DataFrame(

    historia_csv

).to_csv(


    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)







print()

print("================================")

print("ZAKOŃCZONO")

print("================================")



print(

    "Pamięć:",

    PLIK_PAMIEC

)



print(

    "Ocena:",

    PLIK_OCENA

)



print(

    "Predykcje:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_grupy.csv"

    )

)



print(

    "Historia:",

    os.path.join(

        KATALOG_PREDYKCJI,

        "predykcja_z_wynikiem.csv"

    )

)
# =====================================================
# LABORATORIUM V2
# ANALIZA PAMIĘCI + PEWNOŚCI + KLAS + PREDYKCJI
# FRAGMENT 1/2
# =====================================================


import os
import json
import pandas as pd
import numpy as np

from datetime import datetime



# =====================================================
# KONFIGURACJA
# =====================================================


KATALOG_MODELU = (
    r"modele_dataBase_futbol_trend"
    r"\siec_05_start_raw"
)


NAZWA_BAZY = "dataBase_futbol_trend"


NAZWA_MODELU = os.path.basename(
    KATALOG_MODELU
)



# =====================================================
# LABORATORIUM
# =====================================================


KATALOG_LABORATORIUM = os.path.join(
    "laboratorium",
    NAZWA_BAZY,
    NAZWA_MODELU
)



os.makedirs(
    KATALOG_LABORATORIUM,
    exist_ok=True
)



# =====================================================
# PLIKI WEJŚCIOWE
# =====================================================


PLIK_KLASY = os.path.join(
    KATALOG_MODELU,
    "klasy.json"
)



PLIK_PRED_WYNIK = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_z_wynikiem.csv"
)



PLIK_PRED_GRUPY = os.path.join(
    KATALOG_MODELU,
    "predykcje",
    "predykcja_grupy.csv"
)



PLIK_OCENA = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "ocena.json"
)



PLIK_PAMIEC = os.path.join(
    KATALOG_MODELU,
    "obserwacja",
    "pamiec_obserwacji.json"
)




# =====================================================
# WCZYTANIE KLAS
# =====================================================


with open(
    PLIK_KLASY,
    encoding="utf-8"
) as f:

    klasy = json.load(f)



ID_NA_WYNIK = {

    int(v):k

    for k,v in klasy.items()

}



print(
    "Załadowano klas:",
    len(ID_NA_WYNIK)
)



# =====================================================
# WCZYTANIE HISTORII Z WYNIKAMI
# =====================================================


df_historia = pd.read_csv(

    PLIK_PRED_WYNIK,

    sep=";",

    encoding="utf-8"

)



print(
    "Historia:",
    len(df_historia)
)



# =====================================================
# WCZYTANIE AKTUALNYCH PREDYKCJI
# =====================================================


df_predykcja = pd.read_csv(

    PLIK_PRED_GRUPY,

    sep=";",

    encoding="utf-8"

)



print(
    "Aktualne predykcje:",
    len(df_predykcja)
)



# =====================================================
# WCZYTANIE OCENY MODELU
# =====================================================


if os.path.exists(PLIK_OCENA):


    with open(

        PLIK_OCENA,

        encoding="utf-8"

    ) as f:

        ocena_modelu = json.load(f)


else:


    ocena_modelu = {}




# =====================================================
# WCZYTANIE PAMIĘCI OBSERWACJI
# =====================================================


if os.path.exists(PLIK_PAMIEC):


    with open(

        PLIK_PAMIEC,

        encoding="utf-8"

    ) as f:

        pamiec_obserwacji = json.load(f)


else:


    pamiec_obserwacji = {}




print(
    "Pamięć obserwacji:",
    len(pamiec_obserwacji)
)




# =====================================================
# ANALIZA KLAS
# =====================================================


analiza_klas = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    ilosc = len(dane)



    if ilosc == 0:


        analiza_klas[str(id_grupy)] = {


            "wynik":

            wynik,


            "ilosc_predykcji":

            0,


            "trafienia":

            0,


            "skutecznosc":

            0,


            "rzeczywisty_rozkład":

            {}

        }


        continue




    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()




    rozklad = (

        dane["wynik_rzeczywisty"]

        .value_counts(normalize=True)

        .to_dict()

    )




    analiza_klas[str(id_grupy)] = {


        "wynik":

        wynik,


        "ilosc_predykcji":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        ),



        "rzeczywisty_rozkład":

        rozklad

    }




# =====================================================
# ANALIZA PEWNOŚCI DYNAMICZNA
# =====================================================


analiza_pewnosci = {}




df_historia = df_historia.sort_values(
    "pewnosc"
)




# 10 równych grup według ilości danych

df_historia["koszyk_pewnosci"] = pd.qcut(

    df_historia["pewnosc"],

    q=10,

    duplicates="drop"

)




for koszyk, dane in df_historia.groupby(

    "koszyk_pewnosci",

    observed=True

):


    ilosc = len(dane)



    trafienia = (

        dane["wynik_predykcji"]

        ==

        dane["wynik_rzeczywisty"]

    ).sum()



    analiza_pewnosci[str(koszyk)] = {


        "ilosc":

        int(ilosc),


        "trafienia":

        int(trafienia),


        "skutecznosc":

        float(

            trafienia / ilosc

        )

    }




# =====================================================
# ANALIZA PEWNOŚCI DLA KAŻDEJ KLASY
# =====================================================


analiza_pewnosci_klasy = {}




for id_grupy, wynik in ID_NA_WYNIK.items():


    dane_klasy = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]



    if len(dane_klasy) == 0:

        continue




    dane_klasy = dane_klasy.copy()



    dane_klasy["koszyk"] = pd.qcut(

        dane_klasy["pewnosc"],

        q=10,

        duplicates="drop"

    )



    koszyki = {}



    for koszyk,dane in dane_klasy.groupby(

        "koszyk",

        observed=True

    ):



        ilosc = len(dane)



        trafienia = (

            dane["wynik_predykcji"]

            ==

            dane["wynik_rzeczywisty"]

        ).sum()



        koszyki[str(koszyk)] = {


            "ilosc":

            int(ilosc),


            "trafienia":

            int(trafienia),


            "skutecznosc":

            float(

                trafienia / ilosc

            )

        }




    analiza_pewnosci_klasy[str(id_grupy)] = {


        "wynik":

        wynik,


        "progi_pewnosci":

        koszyki

    }




# KONIEC FRAGMENTU 1/2
# =====================================================
# LABORATORIUM V2
# ANALIZA PAMIĘCI + PEWNOŚCI + KLAS + PREDYKCJI
# FRAGMENT 2/2
# =====================================================


# =====================================================
# ANALIZA ODCHYLEŃ
# (CO SIEĆ TYPOWAŁA VS CO FAKTYCZNIE WYPADŁO)
# =====================================================


analiza_odchylen = {}



for id_grupy, wynik in ID_NA_WYNIK.items():


    dane = df_historia[

        df_historia["id_grupy"]

        ==

        id_grupy

    ]


    if len(dane) == 0:

        continue



    rozklad = (

        dane["wynik_rzeczywisty"]

        .value_counts(normalize=True)

        .to_dict()

    )



    uporzadkowane = sorted(

        rozklad.items(),

        key=lambda x:x[1],

        reverse=True

    )



    analiza_odchylen[str(id_grupy)] = {


        "wynik_typowany":

        wynik,


        "ilosc":

        int(len(dane)),


        "najczestsze_wyniki_rzeczywiste":

        dict(uporzadkowane[:10]),


        "czy_odwrócony_wzorzec":

        (
            uporzadkowane[0][0] != wynik
            if len(uporzadkowane)>0
            else False
        )

    }




# =====================================================
# ANALIZA PAMIĘCI OBSERWACJI
# =====================================================


analiza_pamieci = {


    "ilosc_meczow":

    len(pamiec_obserwacji),


    "zmiany_predykcji":0,


    "pierwsze_obserwacje":0

}



for mecz, obserwacje in pamiec_obserwacji.items():


    for obs in obserwacje:


        if obs.get(
            "pierwsza_obserwacja"
        ):

            analiza_pamieci[
                "pierwsze_obserwacje"
            ] += 1



        if obs.get(
            "zmiana_predykcji"
        ):

            analiza_pamieci[
                "zmiany_predykcji"
            ] += 1




# =====================================================
# ANALIZA AKTUALNYCH PREDYKCJI
# =====================================================


analiza_przyszlych = []



for _,mecz in df_predykcja.iterrows():


    id_grupy = int(
        mecz["id_grupy"]
    )


    wynik = str(
        mecz["wynik_predykcji"]
    )


    pewnosc = float(
        mecz["pewnosc"]
    )



    wiedza = analiza_klas.get(

        str(id_grupy),

        {}

    )



    pewnosc_klasy = analiza_pewnosci_klasy.get(

        str(id_grupy),

        {}

    )



    odchylenie = analiza_odchylen.get(

        str(id_grupy),

        {}

    )


    analiza_przyszlych.append(


        {


            "id_meczu":

            mecz["id_meczu"],



            "id_grupy":

            id_grupy,



            "wynik_predykcji":

            wynik,



            "pewnosc":

            pewnosc,



            "historyczna_skutecznosc_klasy":

            wiedza.get(

                "skutecznosc",

                0

            ),



            "najczestszy_realny_wynik":

            (
                max(

                    wiedza.get(

                        "rzeczywisty_rozkład",

                        {}

                    ),

                    key=wiedza.get(

                        "rzeczywisty_rozkład",

                        {}

                    ).get

                )

                if wiedza.get(

                    "rzeczywisty_rozkład"

                )

                else None
            ),



            "czy_odwrócony_wzorzec":

            odchylenie.get(

                "czy_odwrócony_wzorzec",

                False

            )

        }

    )




df_analiza_predykcji = pd.DataFrame(

    analiza_przyszlych

)



df_analiza_predykcji.to_csv(


    os.path.join(

        KATALOG_LABORATORIUM,

        "analiza_przyszlych_predykcji.csv"

    ),


    sep=";",


    index=False,


    encoding="utf-8"

)




